INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66088258', 66088258, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Perkebunan', 'Dokumen Perencanaan Jalan Produksi Komoditas Perkebunan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kab.) | Jawa Barat, Bandung Barat (Kab.)', 120000000, 'May 2026', 'APBD', 1, 1, '1 Paket', '1. Melaksanakan persiapan, survey lapangan, dan pengukuran. 2. Melakukan Analisa dan Perencanaan Teknis 3. Membuat Gambar Teknik 4. Menyusun Rencana Kerja dan Syarat (RKS) 5. Perhitungan Volume Pekerjaan 6. Menyusun Rencana Anggaran Biaya (RAB) 7. Menyusun Jadwal Pelaksanaan', '1. Persiapan terdiri dari mempersiapkan surat – surat untuk keperluan kelancaran pelaksanaan pekerjaan apabila diperlukan dan mempersiapkan tenaga ahli dan tenaga pendukung yang diperlukan. 2. Survey lapangan terdiri dari penyediaan alat ukur atau peralatan survey (jika diperlukan), dokumentasi kondisi awal, dan pengukuran lokasi. 3. Analisa dan Perencanaan Teknis terdiri dari perhitungan teknis konstruksi, analisa struktur, analisa kapasitas dan kebutuhan teknis, penentuan spesifikasi material, dan standar mutu pekerjaan. 4. Pembuatan gambar teknik terdiri dari gambar situasi, site plan, denah, tampak dan potongan, detail konstruksi, detail struktur, dan detail dimensi pekerjaan. 5. Penyusunan Rencana Kerja dan Syarat (RKS) berisi Persyaratan bahan/material, Metode pelaksanaan pekerjaan, Standar mutu, Pengujian pekerjaan, Ketentuan pelaksanaan di lapangan, dan Keselamatan kerja (K3). 6. Perhitungan volume pekerjaan terdiri dari Perhitungan kuantitas setiap item pekerjaan, Rekapitulasi volume pekerjaan, Dasar penyusunan anggaran. 7. Penyusunan Rencana Anggaran Biaya (RAB) terdiri dari Daftar item pekerjaan, Analisa harga satuan pekerjaan (AHSP), Harga bahan, upah, dan alat, Total biaya pekerjaandan Rekap biaya keseluruhan. 8. Penyusunan Jadwal Pelaksanaan terdiri dari time schedule dan kurva S.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 2, 2522974);
