INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66090183', 66090183, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Sekretariat Jenderal Komdigi', 'Lisensi Google AI Pro 2 TB', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 5908000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '( 1, OK, @ 5908000 )', '1. Lisensi Google AI Pro 2 TB ( 1, OK, @ 5908000 );', '1. Fitur Utama Kecerdasan Buatan Akses Gemini Advanced: Mendapatkan akses ke model AI paling mutakhir dari Google (seperti Gemini 1.5 Pro) yang memiliki kemampuan penalaran, pengkodean, dan kreativitas yang jauh lebih tinggi dibanding versi gratis. Gemini di Google Workspace: Integrasi langsung "AI Assistant" di dalam Gmail, Google Docs, Slides, Sheets, dan Meet versi pribadi. Anda bisa menulis email, merangkum dokumen, atau membuat gambar presentasi secara instan. Jendela Konteks Besar: Kemampuan untuk mengunggah dokumen tebal atau ribuan baris kode untuk dianalisis sekaligus. 2. Kapasitas Penyimpanan & Manfaat Google One Penyimpanan 2 TB: Ruang simpan besar yang terbagi untuk Google Drive, Gmail, dan Google Photos. Fitur Foto Premium: Akses ke alat pengeditan foto berbasis AI di Google Photos, seperti Magic Eraser, Portrait Light, dan Sky Suggestions. Keamanan Ekstra: Pemantauan dark web untuk informasi pribadi Anda dan perlindungan VPN (tergantung ketersediaan wilayah). 3. Aksesibilitas dan Teknis Platform: Tersedia melalui browser web serta aplikasi Gemini dan Google One di Android dan iOS. Metode Langganan: Berbasis langganan bulanan atau tahunan melalui Google Play Store atau Apple App Store. Berbagi Keluarga: Kapasitas penyimpanan 2 TB bisa dibagikan dengan hingga 5 anggota keluarga lainnya, namun fitur AI (Gemini Advanced) hanya bisa dinikmati oleh pemilik akun utama.', 5908000, 'high', 'Pengadaan lisensi AI versi personal dengan fitur konsumtif seperti berbagi keluarga, Google Photos premium, dan langganan melalui app store kurang selaras dengan kebutuhan kedinasan. Spesifikasi menunjukkan produk untuk akun pribadi, bukan layanan enterprise/pemerintahan, sehingga seluruh nilai pengadaan berindikasi tidak tepat guna.', NULL, NULL, 3, 1, 1, 1, 1, 2523515);
