INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66090155', 66090155, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Sekretariat Jenderal Komdigi', 'Lisensi Antivirus Kaspersky Premium', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 2668000, 'July 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '( 4, OK, @ 667000 )', '1. Lisensi Antivirus Kaspersky Premium ( 4, OK, @ 667000 );', '1. Nama Produk/Layanan Lisensi Perangkat Lunak Keamanan Siber: Kaspersky Premium 2. Lingkup Perlindungan (Security & Performance) Antivirus Real-Time: Perlindungan terhadap virus, malware, ransomware, dan ancaman zero-day. Safe Browsing & Anti-Phishing: Pemblokiran situs web berbahaya dan upaya pencurian data melalui email atau tautan palsu. Firewall & Network Attack Blocker: Melindungi lalu lintas data jaringan dan mencegah akses tidak sah ke perangkat. Performance Optimization: Fitur pembersihan file duplikat, manajemen aplikasi, dan Gaming/Do Not Disturb Mode untuk menjaga performa perangkat saat bekerja. 3. Fitur Privasi dan Identitas (Privacy & Identity) Unlimited VPN: Layanan koneksi aman terenkripsi tanpa batasan kuota harian. Password Manager: Pengelola kata sandi aman tingkat premium untuk menyimpan kredensial login dan dokumen sensitif. Data Leak Checker: Pemantauan alamat email dan nomor telepon terhadap kebocoran data di internet (global). Identity Protection Wallet: Penyimpanan dokumen identitas dalam format terenkripsi yang dapat diakses di berbagai perangkat. 4. Ketentuan Lisensi dan Kompatibilitas Durasi Lisensi: Minimal 1 (satu) tahun Jumlah Perangkat: Tersedia dalam opsi multi-perangkat (sesuai volume pengadaan). Kompatibilitas Sistem: Harus dapat berjalan di sistem operasi Windows (minimal Windows 7 SP1+), macOS, Android, dan iOS. Manajemen Lisensi: Terpusat melalui konsol manajemen berbasis web (My Kaspersky) untuk memantau status keamanan seluruh perangkat yang terdaftar.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2524230);
