INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66090196', 66090196, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Sekretariat Jenderal Komdigi', 'Lisensi Zoom', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 10000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '( 1, OK, @ 10000000 )', '1. Lisensi Zoom ( 1, OK, @ 10000000 );', '1. Nama Layanan/Produk Platform Kolaborasi dan Pertemuan Daring: Zoom Workplace (Tipe Business / Enterprise). 2. Kapasitas dan Durasi Pertemuan (Meeting Features) Kapasitas Peserta: Minimal 300 peserta per pertemuan (untuk tipe Business) atau hingga 1.000 peserta (untuk tipe Enterprise). Durasi Pertemuan: Tanpa batas waktu (hingga 30 jam per sesi). Whiteboard: Akses ke papan tulis digital kolaboratif tanpa batas (Unlimited Whiteboards). Breakout Rooms: Fitur pembagian ruang rapat kecil dalam satu sesi besar. 3. Fitur Kecerdasan Buatan (Zoom AI Companion) Meeting Summary: Pembuatan ringkasan rapat otomatis berbasis AI yang dapat dikirim ke email peserta. Smart Recording: Rekaman awan yang dilengkapi dengan pembagian bab otomatis (chapters) dan sorotan penting (highlights). AI Compose: Asisten penulisan pesan chat dan email undangan rapat. 4. Penyimpanan dan Manajemen Konten (Cloud Storage) Cloud Recording: Kapasitas penyimpanan rekaman di awan (minimal 5 GB hingga Unlimited, tergantung tipe lisensi). Transkripsi Otomatis: Fitur konversi suara ke teks secara real-time selama rapat berlangsung. 5. Keamanan dan Administrasi (Security & Admin) Single Sign-On (SSO): Integrasi dengan sistem masuk tunggal instansi untuk keamanan akses. End-to-End Encryption (E2EE): Enkripsi tingkat tinggi untuk menjaga kerahasiaan komunikasi. Admin Portal: Konsol manajemen pusat untuk mengatur lisensi pengguna, melihat laporan analitik penggunaan, dan mengatur kebijakan keamanan organisasi. Managed Domains: Kemampuan untuk menambahkan dan mengelola pengguna di bawah domain email instansi secara otomatis. 6. Ketentuan Lisensi & Teknis Durasi Lisensi: Minimal 1 (satu) tahun anggaran. Model Lisensi: Berbasis pengguna bernama (Named User). Kompatibilitas: Mendukung Windows, macOS, Linux, iOS, dan Android, serta dapat diakses via browser web. Interoperabilitas: Dapat terhubung dengan perangkat keras ruang rapat (H.323/SIP).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2524655);
