INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66090214', 66090214, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Sekretariat Jenderal Komdigi', 'Lisensi Cloud Hosting', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 8820000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 12, OB, @ 735000 )', '1. Lisensi Cloud Hosting ( 12, OB, @ 735000 );', '2. Spesifikasi Sumber Daya (Resources) VCPU: Minimal 2 Core (atau sesuai beban aplikasi). Memory (RAM): Minimal 4 GB (DDR4/DDR5) dengan jaminan alokasi tetap (Dedicated). Penyimpanan (Storage): Minimal 100 GB menggunakan teknologi SSD atau NVMe untuk kecepatan baca/tulis data yang optimal. Sistem Operasi: Dukungan terhadap Linux (Ubuntu/CentOS/Debian) atau Windows Server (disertai lisensi resmi). 3. Konektivitas dan Bandwidth Bandwidth: Tanpa batasan kuota bulanan (Unmetered Bandwidth) dengan port speed minimal 100 Mbps hingga 1 Gbps. Dedicated IP: Minimal 1 (satu) alamat IPv4 publik statis. Uptime SLA: Jaminan ketersediaan layanan (Service Level Agreement) minimal 99,9% per bulan. 4. Keamanan dan Kepatuhan (Security & Compliance) Lokasi Data Center: Harus berlokasi di Indonesia (sesuai regulasi PP No. 71 Tahun 2019 tentang Penyelenggaraan Sistem dan Transaksi Elektronik). SSL Certificate: Termasuk sertifikat SSL (Let\'s Encrypt atau komersial) untuk enkripsi jalur komunikasi (HTTPS). Backup & Recovery: Fitur pencadangan data otomatis harian (Daily Automated Backup) dengan masa simpan (retention) minimal 7 hari. Keamanan Jaringan: Dilengkapi dengan Firewall, proteksi Anti-DDoS, dan pemindaian malware secara berkala.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2524659);
