INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66090167', 66090167, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Sekretariat Jenderal Komdigi', 'Lisensi Grammarly', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 2500000, 'May 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '( 1, OK, @ 2500000 )', '1. Lisensi Grammarly ( 1, OK, @ 2500000 );', 'Nama Layanan/Produk Perangkat Lunak Asistensi Penulisan Berbasis AI: Grammarly Premium atau Grammarly Business. 2. Fitur Koreksi Bahasa (Writing Enhancement) Koreksi Tata Bahasa & Ejaan: Koreksi otomatis pada tingkat lanjut untuk tata bahasa (grammar), ejaan (spelling), dan tanda baca (punctuation). Koreksi Kejelasan (Clarity): Fitur untuk mendeteksi kalimat yang bertele-tele dan memberikan saran penulisan ulang agar lebih padat dan jelas. Penyesuaian Nada (Tone Adjustments): Memberikan rekomendasi agar gaya penulisan sesuai dengan target audiens (misal: formal, percaya diri, atau ramah). Kekayaan Kosakata (Vocabulary Enhancement): Saran sinonim untuk menghindari pengulangan kata dan meningkatkan profesionalisme tulisan. 3. Keamanan dan Integritas Dokumen Plagiarism Checker: Pemindaian teks terhadap miliaran halaman web dan artikel ProQuest untuk memastikan orisinalitas tulisan. Citations: Fitur otomatis untuk membantu pembuatan kutipan/referensi (APA, MLA, Chicago). 4. Integrasi dan Aksesibilitas Lintas Platform: Harus tersedia sebagai ekstensi browser (Chrome, Edge, Safari, Firefox), aplikasi desktop (Windows/macOS), dan integrasi langsung dengan Microsoft Office (Word & Outlook). Akses Seluler: Tersedia dalam bentuk keyboard virtual atau aplikasi untuk perangkat Android dan iOS. Integrasi Web Apps: Dapat berfungsi secara real-time pada platform kolaborasi seperti Google Docs, Gmail, Slack, dan LinkedIn. 5. Fitur Administrasi (Khusus Tipe Business/Enterprise) Admin Panel: Konsol terpusat untuk mengelola lisensi pengguna, memantau penggunaan, dan melihat analitik peningkatan kualitas tulisan tim. Style Guide: Kemampuan untuk membuat panduan gaya penulisan khusus instansi (misal: istilah baku atau terminologi teknis organisasi). Single Sign-On (SSO): Dukungan autentikasi terpusat untuk keamanan akses akun (opsional sesuai kebijakan IT). 6. Ketentuan Lisensi Durasi Lisensi: Minimal 1 (satu) tahun anggaran. Model Langganan: Berbasis pengguna (per user) dengan sistem pembayaran tahunan. Pembaruan: Mendukung pembaruan fitur dan algoritma AI secara otomatis selama masa langganan aktif.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2525491);
