INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66054934', 66054934, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Pemeliharaan Personal Computer/Notebook', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 6570000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 Unit', 'Pekerjaan layanan pemeliharaan preventif dan korektif untuk perangkat PC desktop dan/atau notebook milik satuan kerja guna memastikan perangkat selalu dalam kondisi laik operasi, aman, dan siap pakai untuk mendukung kelancaran tugas kedinasan, yang meliputi pemeriksaan berkala, pembersihan, diagnosis gangguan, perbaikan/penanganan kerusakan, optimasi kinerja, penanganan kendala sistem operasi/aplikasi standar perkantoran, dukungan konektivitas jaringan/periferal, serta penyusunan laporan hasil pemeliharaan dan rekomendasi tindak lanjut per perangkat.', 'Spesifikasi layanan minimal mencakup (i) pemeliharaan preventif terjadwal dan pemeliharaan korektif berbasis aduan (on call) melalui mekanisme tiket/helpdesk; (ii) layanan dapat dilakukan remote dan/atau on-site sesuai kebutuhan; (iii) kegiatan meliputi pengecekan fungsi komponen, pembersihan internal/eksternal, pembaruan konfigurasi yang diperlukan, pemindaian malware, troubleshooting hardware/software, reinstall/restore sistem (apabila diperlukan) dengan prosedur pengamanan data (backup/konfirmasi pengguna) dan kepatuhan keamanan informasi; (iv) penyedia menyiapkan teknisi kompeten serta peralatan kerja, dan memberikan dokumentasi perbaikan (hasil diagnosa, tindakan, penggantian komponen bila ada, serta status akhir) dalam laporan berkala; (v) standar waktu respons/penyelesaian dan cakupan suku cadang/jaminan layanan ditetapkan dalam SLA/KAK sesuai kebutuhan satker serta pagu/kontrak, dengan penganggaran berpedoman pada Standar Biaya Masukan TA 2026 (PMK Nomor 32 Tahun 2025).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2525697);
