INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093945', 66093945, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Sewa Kendaraan', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 180000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 180, Hari, @ 1000000 )', '1. Sewa Kendaraan ( 180, Hari, @ 1000000 );', 'Sewa kendaraan merupakan penyediaan sarana transportasi yang digunakan untuk mendukung kelancaran pelaksanaan kegiatan operasional program, khususnya dalam rangka mobilitas tim pelaksana kegiatan di lapangan. Fasilitas ini diperlukan untuk menunjang kegiatan koordinasi, monitoring, evaluasi, pembinaan, serta pelaksanaan berbagai kegiatan program di lokasi yang membutuhkan akses transportasi yang memadai. Kegiatan sewa kendaraan direncanakan selama 180 hari dengan satuan biaya sebesar Rp1.000.000 per hari. Kendaraan yang disewa digunakan untuk mendukung perjalanan dinas tim pelaksana program dalam melaksanakan tugas-tugas operasional, termasuk kunjungan lapangan, koordinasi dengan pemerintah daerah, pendampingan kegiatan di lokasi program, serta kegiatan lain yang berkaitan dengan pelaksanaan program. Kendaraan yang disediakan dalam kegiatan sewa ini diharapkan dalam kondisi layak jalan, aman, dan memenuhi standar operasional transportasi, sehingga dapat digunakan secara optimal untuk mendukung kegiatan di lapangan. Penggunaan kendaraan juga disesuaikan dengan kebutuhan kegiatan serta mempertimbangkan efisiensi dan efektivitas pelaksanaan tugas. Dengan tersedianya fasilitas sewa kendaraan ini, diharapkan mobilitas tim pelaksana kegiatan dapat berjalan dengan lancar sehingga berbagai kegiatan koordinasi, monitoring, evaluasi, dan pendampingan program dapat dilaksanakan secara tepat waktu dan efektif sesuai dengan rencana kerja yang telah ditetapkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2525970);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66056194', 66056194, 'analyze_legacy', 'Kab. Wonosobo', 'kabkota', 'Kecamatan Selomerto', 'Belanja Pakaian Olahraga', 'Barang', 'E-Purchasing', 'Jawa Tengah, Wonosobo (Kab.)', 9200000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Pakaian Olah Raga/training pack;', ';', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2525971);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094053', 66094053, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Fullboard dalam rangka Monitoring dan Evaluasi', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 33000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 55, OH, @ 600000 )', '1. Paket Meeting Fullboard dalam rangka Monitoring dan Evaluasi ( 55, OH, @ 600000 );', 'Paket meeting fullboard dalam rangka kegiatan Monitoring dan Evaluasi merupakan layanan penyelenggaraan rapat atau pertemuan yang disediakan oleh pihak hotel atau tempat pertemuan yang memiliki fasilitas memadai untuk mendukung pelaksanaan kegiatan secara efektif dan kondusif. Kegiatan ini dialokasikan sebanyak 55 Orang Hari (OH) dengan satuan biaya sebesar Rp600.000 per orang per hari. Paket meeting fullboard mencakup penyediaan ruang pertemuan yang representatif dan nyaman, dengan kapasitas yang memadai sesuai jumlah peserta kegiatan. Ruangan dilengkapi dengan berbagai fasilitas pendukung kegiatan rapat, seperti meja dan kursi sesuai tata letak pertemuan (classroom, U-shape, atau theater), LCD proyektor, layar proyektor, sound system, microphone, papan tulis atau flipchart, serta akses listrik dan jaringan internet yang mendukung kegiatan presentasi, diskusi, serta penyampaian laporan selama kegiatan berlangsung. Selain penyediaan ruang pertemuan, paket fullboard juga mencakup konsumsi bagi peserta selama kegiatan, yang terdiri dari tiga kali makan utama (sarapan, makan siang, dan makan malam) serta dua kali coffee break setiap hari kegiatan. Konsumsi disediakan oleh penyedia jasa dengan memperhatikan standar kebersihan, kualitas makanan, serta kecukupan gizi bagi seluruh peserta kegiatan. Paket ini juga mencakup fasilitas akomodasi atau penginapan bagi peserta, berupa kamar hotel yang layak dan nyaman sesuai standar tempat kegiatan. Fasilitas kamar meliputi tempat tidur, kamar mandi dalam, perlengkapan mandi, pendingin ruangan, serta fasilitas pendukung lainnya yang diperlukan bagi peserta selama kegiatan berlangsung. Selain itu, penyedia layanan juga memberikan dukungan teknis dan layanan operasional, seperti penataan ruang rapat, kesiapan peralatan presentasi, kebersihan ruangan, serta pelayanan konsumsi bagi peserta kegiatan. Dukungan tersebut diberikan untuk memastikan bahwa kegiatan monitoring dan evaluasi dapat berjalan dengan tertib, efektif, dan lancar. Dengan tersedianya paket meeting fullboard ini, diharapkan kegiatan monitoring dan evaluasi pelaksanaan program dapat terlaksana secara optimal, sehingga dapat menghasilkan pembahasan yang komprehensif mengenai perkembangan kegiatan, identifikasi permasalahan, serta penyusunan rekomendasi perbaikan untuk meningkatkan kualitas pelaksanaan program ke depan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2525972);
