INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094909', 66094909, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting (35 Orang x 3 hari)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 70420000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 70, OP, @ 1006000 )', '1. Paket Meeting (35 Orang x 3 hari) ( 70, OP, @ 1006000 );', 'Kegiatan Identifikasi dan Verifikasi Operasi dan Pemeliharaan (OP) Jaringan Irigasi Tersier dilaksanakan dalam rangka memastikan kesesuaian pelaksanaan kegiatan dengan ketentuan teknis, validitas data lapangan, serta ketepatan administrasi dan pelaporan. Salah satu tahapan penting dalam kegiatan ini adalah pelaksanaan paket meeting untuk pembahasan hasil identifikasi dan verifikasi secara komprehensif. Meeting dilaksanakan selama 3 (tiga) hari dengan melibatkan 35 (tiga puluh lima) orang peserta yang terdiri dari unsur teknis, pengelola kegiatan, serta unit kerja terkait lainnya. Kegiatan meliputi pemaparan data, klarifikasi hasil lapangan, pembahasan teknis, serta penyusunan kesimpulan dan rekomendasi tindak lanjut. Kebutuhan paket meeting dihitung sebanyak 70 (tujuh puluh) orang/kali dengan harga satuan Rp1.006.000,- sehingga total anggaran sebesar Rp70.420.000,-. Paket meeting mencakup penyediaan ruang pertemuan, konsumsi (makan dan coffee break), serta fasilitas dan perlengkapan rapat sesuai standar biaya yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526024);
