INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094012', 66094012, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Perbanyakan Laporan Akhir Tahun', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 2000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 20, PKT, @ 100000 )', '1. Perbanyakan Laporan Akhir Tahun ( 20, PKT, @ 100000 );', 'Perbanyakan Laporan Akhir Tahun merupakan kegiatan penggandaan dokumen laporan yang dilakukan untuk mendukung proses penyampaian dan distribusi hasil pelaksanaan kegiatan program kepada pihak-pihak terkait. Kegiatan ini dialokasikan sebanyak 20 paket (PKT) dengan satuan biaya sebesar Rp100.000 per paket, yang digunakan untuk mencetak dan menggandakan dokumen laporan akhir tahun secara lengkap. Laporan akhir tahun merupakan dokumen yang memuat ringkasan pelaksanaan kegiatan selama satu tahun anggaran, meliputi uraian kegiatan yang telah dilaksanakan, capaian program, realisasi penggunaan anggaran, kendala yang dihadapi, serta rekomendasi untuk pelaksanaan kegiatan pada periode selanjutnya. Dokumen ini disusun sebagai bentuk pertanggungjawaban pelaksanaan program sekaligus sebagai bahan evaluasi bagi pihak-pihak terkait. Kegiatan perbanyakan laporan dilakukan melalui proses pencetakan, penggandaan, penyusunan dokumen, serta penjilidan, sehingga laporan tersaji secara rapi, sistematis, dan mudah dipahami. Dokumen laporan yang telah diperbanyak kemudian didistribusikan kepada pimpinan, unit kerja terkait, serta pihak lain yang berkepentingan sebagai bahan informasi, dokumentasi, dan referensi dalam pelaksanaan program. Dengan adanya kegiatan perbanyakan laporan akhir tahun ini, diharapkan proses dokumentasi, pelaporan, serta penyebarluasan informasi mengenai hasil pelaksanaan kegiatan program dapat berjalan dengan baik, sehingga seluruh pemangku kepentingan dapat memperoleh gambaran yang jelas mengenai capaian dan perkembangan kegiatan selama satu tahun pelaksanaan program.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526157);
