INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094916', 66094916, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Belanja Jasa Lainnya', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 95000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Update Data Spasial Pada Sistem Informasi Jaringan Irigasi ( 1, Paket, @ 95000000 );', 'Kegiatan Update Data Spasial pada Sistem Informasi Jaringan Irigasi dilaksanakan dalam rangka meningkatkan akurasi, keterbaruan, dan integritas data jaringan irigasi sebagai dasar perencanaan, pelaksanaan, monitoring, dan evaluasi kegiatan pengelolaan irigasi. Data spasial yang mutakhir sangat diperlukan untuk memastikan kesesuaian antara kondisi eksisting di lapangan dengan informasi yang tersaji dalam sistem. Ruang lingkup kegiatan meliputi pengumpulan dan verifikasi data spasial jaringan irigasi, pembaruan koordinat dan atribut jaringan (saluran, bangunan pelengkap, luas layanan, dan komponen pendukung lainnya), pengolahan data menggunakan perangkat lunak Sistem Informasi Geografis (SIG), serta integrasi dan sinkronisasi data ke dalam Sistem Informasi Jaringan Irigasi yang digunakan oleh unit kerja. Kegiatan ini juga mencakup validasi hasil pembaruan serta penyusunan laporan teknis sebagai dokumentasi resmi. Volume kegiatan direncanakan sebanyak 1 (satu) paket dengan nilai anggaran sebesar Rp95.000.000,- (sembilan puluh lima juta rupiah). Paket pekerjaan mencakup seluruh proses mulai dari persiapan, survei lapangan (apabila diperlukan), pengolahan dan pemutakhiran database, hingga finalisasi dan serah terima hasil pembaruan data. Output yang diharapkan adalah tersedianya basis data spasial jaringan irigasi yang akurat, terintegrasi, dan siap digunakan sebagai referensi dalam pengambilan keputusan serta penyusunan kebijakan pengelolaan irigasi. Dengan pelaksanaan kegiatan ini, sistem informasi jaringan irigasi diharapkan menjadi lebih andal, informatif, dan mendukung pengelolaan irigasi yang efektif dan berbasis data.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526183);
