INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094029', 66094029, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Pelatihan Gesi / Nutrition Training', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 184000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 230, OH, @ 800000 )', '1. Paket Meeting Pelatihan Gesi / Nutrition Training ( 230, OH, @ 800000 );', 'Paket meeting pelatihan GESI (Gender Equality and Social Inclusion) / Nutrition Training merupakan layanan penyelenggaraan kegiatan pelatihan yang disediakan oleh hotel atau tempat pertemuan yang memiliki fasilitas memadai untuk mendukung pelaksanaan kegiatan pelatihan secara efektif dan kondusif. Kegiatan ini dialokasikan sebanyak 230 Orang Hari (OH) dengan satuan biaya sebesar Rp800.000 per orang per hari. Paket meeting pelatihan mencakup penyediaan ruang pertemuan atau ruang pelatihan yang representatif dengan kapasitas yang memadai sesuai dengan jumlah peserta kegiatan. Ruangan tersebut dilengkapi dengan berbagai fasilitas pendukung pelatihan, seperti meja dan kursi sesuai tata letak pelatihan (classroom atau kelompok), LCD proyektor, layar proyektor, sound system, microphone, papan tulis atau flipchart, serta akses listrik dan jaringan internet untuk menunjang kegiatan presentasi materi, diskusi kelompok, dan penyampaian informasi selama pelatihan berlangsung. Selain penyediaan ruang pelatihan, paket ini juga mencakup konsumsi bagi peserta selama kegiatan berlangsung, yang umumnya terdiri dari makan siang dan dua kali coffee break setiap hari kegiatan. Konsumsi disediakan oleh pihak penyedia jasa dengan memperhatikan standar kebersihan, kualitas makanan, serta kecukupan gizi bagi peserta pelatihan. Paket meeting pelatihan ini juga dapat mencakup fasilitas pendukung kegiatan, seperti penyediaan peralatan presentasi, air minum, alat tulis peserta (blocknote dan pulpen), serta dukungan layanan teknis dari petugas tempat kegiatan yang membantu dalam penyiapan ruang, pengoperasian peralatan, serta memastikan kegiatan pelatihan dapat berjalan dengan tertib dan lancar. Kegiatan pelatihan GESI / Nutrition Training bertujuan untuk meningkatkan pemahaman dan kapasitas peserta terkait isu kesetaraan gender, inklusi sosial, serta peningkatan kesadaran terhadap aspek gizi dalam pelaksanaan program dan kegiatan pembangunan. Melalui pelatihan ini diharapkan peserta mampu memahami prinsip-prinsip GESI dan aspek nutrisi serta mengintegrasikannya dalam pelaksanaan kegiatan di lapangan. Dengan tersedianya paket meeting pelatihan ini, diharapkan proses pembelajaran, diskusi, dan peningkatan kapasitas peserta dapat berlangsung secara optimal sehingga mendukung tercapainya tujuan program serta meningkatkan kualitas pelaksanaan kegiatan di lapangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526188);
