INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094005', 66094005, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsultan Individu Bidang Rural Finance', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 200000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 10, OB, @ 20000000 )', '1. Konsultan Individu Bidang Rural Finance ( 10, OB, @ 20000000 );', 'Konsultan Individu Bidang Rural Finance merupakan tenaga ahli yang direkrut secara profesional untuk memberikan dukungan teknis dalam kegiatan yang berkaitan dengan penguatan aspek pembiayaan perdesaan, khususnya dalam rangka mendukung pelaksanaan program pembangunan dan pemberdayaan masyarakat di wilayah perdesaan. Kegiatan konsultansi ini dilaksanakan selama 10 Orang Bulan (OB) dengan nilai jasa konsultansi sebesar Rp20.000.000 per bulan. Konsultan bertanggung jawab dalam memberikan analisis, rekomendasi, serta pendampingan teknis terkait pengembangan sistem pembiayaan yang dapat diakses oleh masyarakat, kelompok tani, maupun pelaku usaha di wilayah perdesaan. Lingkup pekerjaan konsultan meliputi penyusunan kajian terkait kondisi pembiayaan perdesaan, identifikasi sumber-sumber pembiayaan yang potensial, serta perumusan strategi penguatan akses pembiayaan bagi pelaku usaha pertanian dan komoditas unggulan di daerah sasaran program. Dalam pelaksanaan tugasnya, konsultan juga melakukan koordinasi dengan tim pelaksana program, pemerintah daerah, lembaga keuangan, serta pemangku kepentingan terkait untuk memastikan bahwa skema pembiayaan yang dirancang dapat diimplementasikan secara efektif dan berkelanjutan. Konsultan turut memberikan masukan dalam penyusunan kebijakan, pedoman teknis, serta rekomendasi model pembiayaan yang sesuai dengan kondisi sosial ekonomi masyarakat perdesaan. Selain itu, konsultan bertugas untuk menyusun laporan hasil kajian, dokumen rekomendasi kebijakan, serta laporan kemajuan kegiatan secara berkala sebagai bentuk pertanggungjawaban atas pelaksanaan tugas konsultansi. Seluruh hasil pekerjaan diharapkan dapat menjadi bahan pertimbangan dalam mendukung keberlanjutan program dan memperkuat sistem pembiayaan di sektor pertanian dan pembangunan perdesaan. Dengan dukungan Konsultan Individu Bidang Rural Finance ini, diharapkan perencanaan dan implementasi strategi pembiayaan perdesaan dapat tersusun secara lebih komprehensif, sehingga mampu meningkatkan akses permodalan, memperkuat kelembagaan ekonomi masyarakat, serta mendukung keberlanjutan program pembangunan di wilayah sasaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526295);
