INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093953', 66093953, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Sewa kendaraan Operasional Kantor R4 (PMU)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 336000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 0, '( 4, Unit, @ 84000000 )', '1. Sewa kendaraan Operasional Kantor R4 (PMU) ( 4, Unit, @ 84000000 );', 'Pengadaan sewa kendaraan operasional kantor roda 4 (R4) untuk kebutuhan PMU dilaksanakan sebanyak 4 (empat) unit kendaraan selama periode kontrak, dengan nilai sebesar Rp84.000.000 per unit. Kendaraan digunakan untuk mendukung kegiatan operasional program, seperti koordinasi, monitoring, supervisi lapangan, serta kegiatan kedinasan lainnya. Kendaraan yang disediakan harus dalam kondisi laik jalan, terawat, memiliki dokumen kendaraan yang lengkap dan sah (STNK aktif), serta diasuransikan sesuai ketentuan yang berlaku. Spesifikasi minimal kendaraan meliputi tipe penumpang/minibus atau setara, kapasitas yang memadai untuk kegiatan operasional, kondisi mesin baik, serta dilengkapi fasilitas standar keselamatan. Biaya sewa mencakup penggunaan kendaraan selama masa kontrak, termasuk perawatan rutin dan pajak kendaraan, sesuai dengan perjanjian kerja sama yang disepakati. Penggunaan kendaraan harus mendukung efektivitas dan kelancaran pelaksanaan kegiatan PMU.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526333);
