INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66090350', 66090350, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Belanja Bahan', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 204260000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Konsumsi rapat koordinasi dengan unit kerja terkait lainnya ( 500, OK, @ 57000 ); 2. Komputer Suplies ( 1, Tahun, @ 1056000 ); 3. Fotocopy dan Pencetakan dokumen ( 1, Tahun, @ 4704000 ); 4. Perbaikan/Upgrade Laptop, Komputer dan Printer ( 1, Paket, @ 30000000 ); 5. Perlengkapan lapang mendukung K3 ( 30, Paket, @ 4000000 ); 6. Langganan Lisensi Aplikasi (Office, Canva, Capcut, dll) ( 1, Tahun, @ 10000000 ); 7. Langganan Penyimpanan online (cloud) dan Lisensi Video Conference ( 1, Tahun, @ 10000000 );', 'Konsumsi Rapat Koordinasi dengan Unit Kerja Terkait Lainnya (500 OK @ Rp57.000) Dialokasikan untuk mendukung pelaksanaan rapat koordinasi dalam rangka Operasional SID Irigasi Tersier, guna sinkronisasi data, pembahasan progres pekerjaan, dan penyelesaian permasalahan teknis. Komputer Supplies (1 Tahun @ Rp1.056.000) Digunakan untuk mendukung kebutuhan administrasi, pengolahan data, dan penyusunan laporan kegiatan SID selama satu tahun anggaran. Fotocopy dan Pencetakan Dokumen (1 Tahun @ Rp4.704.000) Dialokasikan untuk penggandaan, pencetakan, dan penjilidan dokumen teknis maupun administrasi guna memastikan tertib dokumentasi kegiatan SID. Perbaikan/Upgrade Laptop, Komputer dan Printer (1 Paket @ Rp30.000.000) Dialokasikan untuk pemeliharaan, perbaikan, dan peningkatan kapasitas perangkat kerja guna menunjang kelancaran pengolahan data teknis, pemetaan, dan penyusunan dokumen SID. Perlengkapan Lapang Mendukung K3 (30 Paket @ Rp4.000.000) Disediakan untuk mendukung keselamatan dan kesehatan kerja (K3) tim lapangan, seperti rompi, helm, sepatu keselamatan, dan perlengkapan pendukung lainnya selama kegiatan survei dan investigasi. Langganan Lisensi Aplikasi (Office, Canva, CapCut, dll) (1 Tahun @ Rp10.000.000) Dialokasikan untuk mendukung kebutuhan pengolahan dokumen, desain materi, pengolahan data, dan pembuatan bahan presentasi secara legal dan profesional. Langganan Penyimpanan Online (Cloud) dan Lisensi Video Conference (1 Tahun @ Rp10.000.000) Digunakan untuk mendukung penyimpanan data digital, berbagi dokumen, serta pelaksanaan rapat dan koordinasi daring guna meningkatkan efisiensi dan kolaborasi tim dalam operasional SID Irigasi Tersier.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526500);
