INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094028', 66094028, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket MeetingExpo Produk, Kurasi, Pelatihan Packaging dan Branding', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 264000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '2 Paket', '1. Paket Meeting Expo Produk, Kurasi, Pelatihan Packaging dan Branding ( 165, OH, @ 800000 ); 2. Paket Meeting Expo Produk, Kurasi, Pelatihan Packaging dan Branding ( 165, OH, @ 800000 );', 'Paket Meeting Expo Produk, Kurasi, Pelatihan Packaging dan Branding merupakan penyediaan layanan kegiatan pertemuan yang bertujuan untuk mendukung pelaksanaan kegiatan promosi dan pengembangan produk hasil program. Kegiatan ini dilaksanakan sebagai sarana untuk menampilkan produk unggulan, melakukan proses kurasi produk, serta memberikan pelatihan kepada peserta terkait peningkatan kualitas kemasan (packaging) dan penguatan identitas merek (branding) guna meningkatkan daya saing produk di pasar. Paket kegiatan ini mencakup penyediaan ruang pertemuan atau area kegiatan yang memadai sesuai dengan jumlah peserta, serta dilengkapi dengan fasilitas pendukung seperti meja dan kursi, ruang display atau pameran produk, perangkat presentasi (LCD projector dan layar), sound system, serta sarana pendukung lainnya yang diperlukan untuk menunjang kelancaran pelaksanaan kegiatan. Selain itu, paket ini juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung sesuai dengan standar layanan pertemuan. Dengan terselenggaranya kegiatan ini, diharapkan peserta dapat meningkatkan pengetahuan dan keterampilan dalam pengemasan dan pemasaran produk, serta menghasilkan produk yang lebih berkualitas, menarik, dan memiliki nilai jual yang lebih tinggi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526521);
