INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094007', 66094007, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Perbanyakan, Pengiriman dan Fotocopy', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 6000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 12, BLN, @ 500000 )', '1. Perbanyakan, Pengiriman dan Fotocopy ( 12, BLN, @ 500000 );', 'Kegiatan perbanyakan, pengiriman, dan fotocopy dokumen merupakan bagian dari dukungan operasional administrasi yang diperlukan untuk menunjang kelancaran pelaksanaan kegiatan program. Kebutuhan ini dialokasikan selama 12 bulan dengan satuan biaya sebesar Rp500.000 per bulan, yang digunakan untuk mendukung proses penggandaan dokumen, distribusi informasi, serta penyampaian berbagai dokumen kegiatan kepada pihak-pihak terkait. Perbanyakan dan fotocopy dokumen dilakukan untuk memenuhi kebutuhan penggandaan berbagai dokumen penting, seperti laporan kegiatan, materi rapat atau pelatihan, dokumen administrasi, surat menyurat, dokumen teknis, serta bahan presentasi yang diperlukan dalam pelaksanaan kegiatan program. Proses penggandaan dilakukan sesuai dengan kebutuhan kegiatan agar seluruh pihak yang terlibat dapat memperoleh dokumen yang diperlukan secara lengkap dan tepat waktu. Selain itu, komponen ini juga mencakup biaya pengiriman dokumen, baik melalui jasa pengiriman maupun distribusi langsung kepada instansi, mitra kerja, atau pihak terkait lainnya. Pengiriman dokumen dilakukan untuk memastikan bahwa berbagai laporan, surat resmi, maupun dokumen pendukung kegiatan dapat diterima oleh pihak yang berkepentingan secara tepat waktu dan sesuai dengan prosedur administrasi yang berlaku. Dengan adanya dukungan kegiatan perbanyakan, pengiriman, dan fotocopy dokumen ini, diharapkan proses administrasi, dokumentasi, serta koordinasi kegiatan program dapat berjalan dengan lebih efektif, tertib, dan terkelola dengan baik sepanjang periode pelaksanaan kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526574);
