INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094032', 66094032, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 50, OH, @ 600000 )', '1. Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND ( 50, OH, @ 600000 );', 'Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategy dan Keberlanjutan Program UPLAND merupakan penyediaan layanan pertemuan yang bertujuan untuk mendukung proses perumusan strategi pengakhiran program (exit strategy) serta memastikan keberlanjutan hasil dan manfaat program UPLAND setelah masa pelaksanaan program berakhir. Kegiatan ini dilaksanakan sebagai forum diskusi dan koordinasi antar pemangku kepentingan untuk merumuskan langkah-langkah strategis, rencana tindak lanjut, serta mekanisme keberlanjutan program di tingkat pusat maupun daerah. Paket meeting fullboard ini mencakup penyediaan ruang pertemuan yang memadai sesuai dengan jumlah peserta, serta dilengkapi dengan fasilitas pendukung seperti meja dan kursi, pendingin ruangan, LCD projector, layar presentasi, sound system, dan peralatan presentasi lainnya untuk menunjang kelancaran kegiatan. Selain itu, paket fullboard juga mencakup penyediaan konsumsi bagi peserta berupa makan pagi, makan siang, makan malam, serta coffee break selama kegiatan berlangsung sesuai dengan standar layanan pertemuan. Dengan terselenggaranya kegiatan ini, diharapkan dapat dihasilkan rumusan exit strategy yang komprehensif serta strategi keberlanjutan program yang jelas dan terarah sehingga manfaat program UPLAND dapat terus berlanjut dan memberikan dampak positif bagi masyarakat sasaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526668);
