INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66054873', 66054873, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Biaya Pemeliharaan dan Operasional Kendaraan Dinas Pejabat Eselon II', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 38241000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Unit', 'Kegiatan ini berupa penyediaan biaya untuk pemeliharaan dan operasional Kendaraan Dinas yang digunakan Pejabat Eselon II guna menunjang kelancaran pelaksanaan tugas kedinasan, meliputi pemeliharaan preventif (servis berkala sesuai jadwal/pedoman pabrikan) dan korektif (perbaikan kerusakan/penanganan gangguan), penggantian suku cadang dan bahan habis pakai, serta kebutuhan operasional kendaraan yang sah dan dapat dipertanggungjawabkan, termasuk pencatatan administrasi pemeliharaan (bukti servis, kuitansi/nota, dan rekap penggunaan) selama periode pelaksanaan pada Tahun Anggaran berjalan, dengan pembayaran berdasarkan tagihan dan bukti pekerjaan yang valid sesuai ketentuan perbendaharaan serta mengacu pada standar biaya yang berlaku.', 'Pemeliharaan dan operasional dilaksanakan oleh penyedia/bengkel yang kompeten dan legal, menggunakan suku cadang/material yang sesuai spesifikasi kendaraan (minimal setara OEM) dan mengikuti rekomendasi pabrikan, dengan ruang lingkup minimal mencakup servis rutin (pemeriksaan menyeluruh, penggantian oli dan filter, tune-up), perbaikan komponen sesuai kebutuhan (mis. sistem pengereman, kelistrikan, pendinginan, kaki-kaki), penggantian komponen habis pakai (mis. kampas rem, ban, aki, wiper, lampu, cairan pendukung), serta dokumentasi hasil pekerjaan berupa rincian item pekerjaan/parts, nomor part bila ada, tanggal dan kilometer servis, serta rekap biaya periodik; keluaran pekerjaan adalah kendaraan dinas dalam kondisi laik jalan, aman, dan siap operasional, dengan jaminan layanan/garansi pekerjaan sesuai praktik layanan bengkel dan ketentuan dalam dokumen pengadaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526678);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66091664', 66091664, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB PAKPAK BHARAT', 'paket data petugas pencacahan sksppi di kab/kota', 'Barang', 'Pengadaan Langsung', 'Sumatera Utara, Pakpak Bharat (Kab.)', 250000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. paket data petugas pencacahan sksppi di kab/kota ( 5, OB, @ 50000 );', 'sesuai spesifikasi KAK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526679);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094041', 66094041, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Fullboard dalam rangka Monitoring dan Evaluasi', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 50, OH, @ 600000 )', '1. Paket Meeting Fullboard dalam rangka Monitoring dan Evaluasi ( 50, OH, @ 600000 );', 'Paket meeting fullboard dalam rangka kegiatan Monitoring dan Evaluasi merupakan layanan penyelenggaraan rapat atau pertemuan yang disediakan oleh pihak hotel atau tempat pertemuan yang memiliki fasilitas memadai untuk mendukung pelaksanaan kegiatan secara efektif dan kondusif. Kegiatan ini dialokasikan sebanyak 50 Orang Hari (OH) dengan satuan biaya sebesar Rp600.000 per orang per hari. Paket meeting fullboard mencakup penyediaan ruang pertemuan yang representatif dan nyaman, dengan kapasitas yang memadai sesuai jumlah peserta kegiatan. Ruangan dilengkapi dengan berbagai fasilitas pendukung kegiatan rapat, seperti meja dan kursi sesuai tata letak pertemuan (classroom, U-shape, atau theater), LCD proyektor, layar proyektor, sound system, microphone, papan tulis atau flipchart, serta akses listrik dan jaringan internet yang mendukung kegiatan presentasi, diskusi, serta penyampaian laporan selama kegiatan berlangsung. Selain penyediaan ruang pertemuan, paket fullboard juga mencakup konsumsi bagi peserta selama kegiatan, yang terdiri dari tiga kali makan utama (sarapan, makan siang, dan makan malam) serta dua kali coffee break setiap hari kegiatan. Konsumsi disediakan oleh penyedia jasa dengan memperhatikan standar kebersihan, kualitas makanan, serta kecukupan gizi bagi seluruh peserta kegiatan. Paket ini juga mencakup fasilitas akomodasi atau penginapan bagi peserta, berupa kamar hotel yang layak dan nyaman sesuai standar tempat kegiatan. Fasilitas kamar meliputi tempat tidur, kamar mandi dalam, perlengkapan mandi, pendingin ruangan, serta fasilitas pendukung lainnya yang diperlukan bagi peserta selama kegiatan berlangsung. Selain itu, penyedia layanan juga memberikan dukungan teknis dan layanan operasional, seperti penataan ruang rapat, kesiapan peralatan presentasi, kebersihan ruangan, serta pelayanan konsumsi bagi peserta kegiatan. Dukungan tersebut diberikan untuk memastikan bahwa kegiatan monitoring dan evaluasi dapat berjalan dengan tertib, efektif, dan lancar. Dengan tersedianya paket meeting fullboard ini, diharapkan kegiatan monitoring dan evaluasi pelaksanaan program dapat terlaksana secara optimal, sehingga dapat menghasilkan pembahasan yang komprehensif mengenai perkembangan kegiatan, identifikasi permasalahan, serta penyusunan rekomendasi perbaikan untuk meningkatkan kualitas pelaksanaan program ke depan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526680);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66092332', 66092332, 'analyze_legacy', 'Kab. Tana Toraja', 'kabkota', 'DINAS PEMBERDAYAAN MASYARAKAT DAN LEMBANG', 'Belanja Pemeliharaan Alat Angkutan-Alat Angkutan Darat Bermotor-Kendaraan Dinas Bermotor Perorangan', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Tana Toraja (Kab.)', 32500000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Pemeliharaan kendaraan pejabat eselon II; Pemeliharaan kendaraan dinas operasional roda empat; Pemeliharaan Kendaraan Dinas Operasional Roda Dua;', 'Pemeliharaan kendaraan pejabat eselon II; Pemeliharaan kendaraan dinas operasional roda empat; Pemeliharaan Kendaraan Dinas Operasional Roda Dua;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526681);
