INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66055072', 66055072, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Pemeliharaan Kamera Foto dan Lensa', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 90000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 Unit', 'Layanan pemeliharaan preventif dan korektif atas seluruh unit kamera foto dan lensa milik Biro Humas Kemnaker untuk memastikan perangkat selalu laik pakai dalam kegiatan dokumentasi, peliputan, dan publikasi; ruang lingkupnya meliputi pemeriksaan fisik dan fungsi, pembersihan (body, mount, sensor/optik sesuai kebutuhan), pengujian performa (fokus, eksposur, stabilisasi, tombol/port), penyesuaian/kalibrasi minor bila diperlukan, perbaikan kerusakan ringan–sedang (mekanik/elektronik) termasuk penggantian komponen/spare part bila disepakati, serta penyusunan laporan hasil pemeriksaan dan berita acara serah terima setelah uji fungsi dinyatakan normal.', 'Penyedia wajib memiliki kompetensi teknis pemeliharaan kamera dan lensa (diutamakan teknisi bersertifikat/berpengalaman dan/atau service center resmi), menggunakan peralatan kerja yang sesuai (toolset presisi, blower/cleaning kit, alat ukur/kalibrasi yang relevan), menerapkan prosedur kerja aman untuk mencegah kontaminasi debu/jamur dan kerusakan optik/elektronik, menggunakan suku cadang asli/OEM atau setara yang kompatibel (jika ada penggantian), serta menghasilkan keluaran minimal berupa perangkat berfungsi normal tanpa error pada seluruh fitur utama, bukti uji fungsi, laporan pekerjaan (temuan, tindakan perbaikan, komponen yang diganti), dan jaminan layanan purna pemeliharaan sesuai ketentuan kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526692);
