INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094042', 66094042, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND (2 kali x 35 orang)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 42000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 70, OH, @ 600000 )', '1. Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND (2 kali x 35 orang) ( 70, OH, @ 600000 );', 'Kegiatan pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi Program UPLAND dilaksanakan sebagai upaya untuk meningkatkan efektivitas pelaksanaan program serta memperkuat koordinasi antar pihak yang terlibat dalam kegiatan. Pertemuan ini bertujuan untuk memastikan bahwa seluruh tahapan kegiatan program berjalan sesuai dengan rencana, kebijakan, serta target yang telah ditetapkan. Kegiatan ini dilaksanakan sebanyak 2 (dua) kali pertemuan dengan jumlah peserta 35 (tiga puluh lima) orang pada setiap pertemuan, sehingga total kebutuhan 70 Orang Hari (OH). Peserta terdiri dari unsur pengelola program, perwakilan instansi terkait, tim teknis, serta pihak lain yang memiliki keterkaitan dengan pelaksanaan Program UPLAND di wilayah kegiatan. Pelaksanaan pertemuan dilakukan dalam bentuk rapat koordinasi yang difasilitasi dengan paket meeting fullboard, yang mencakup penggunaan ruang pertemuan yang representatif, fasilitas presentasi seperti LCD proyektor, layar, sound system, serta perlengkapan pendukung lainnya. Selain itu, peserta juga mendapatkan konsumsi selama kegiatan berlangsung, yang meliputi makan pagi, makan siang, makan malam, serta coffee break sesuai dengan standar pelayanan kegiatan pertemuan. Materi yang dibahas dalam kegiatan ini meliputi penyampaian perkembangan pelaksanaan Program UPLAND, pembinaan teknis kepada pelaksana kegiatan, pembahasan hasil monitoring di lapangan, evaluasi capaian kegiatan, serta sinkronisasi rencana kerja antar pihak terkait. Selain itu, kegiatan juga memberikan ruang diskusi bagi peserta untuk menyampaikan kendala, masukan, serta usulan solusi guna meningkatkan kualitas pelaksanaan program. Output yang diharapkan dari kegiatan ini adalah tersusunnya kesepahaman bersama terkait pelaksanaan program, adanya rekomendasi perbaikan terhadap kendala yang ditemukan, serta tersusunnya rencana tindak lanjut yang akan dilaksanakan oleh masing-masing pihak. Seluruh proses dan hasil pembahasan akan didokumentasikan dalam bentuk notulen atau laporan kegiatan sebagai bahan evaluasi dan referensi pelaksanaan kegiatan selanjutnya. Dengan dilaksanakannya kegiatan ini, diharapkan koordinasi antar pemangku kepentingan dalam pelaksanaan Program UPLAND dapat berjalan lebih efektif, sehingga tujuan program dapat tercapai secara optimal dan berkelanjutan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526733);
