INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093965', 66093965, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Media Publikasi/presentasi Kegiatan UPLAND', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 482000000, 'March 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 2, Pkt, @ 241000000 )', '1. Media Publikasi/presentasi Kegiatan UPLAND ( 2, Pkt, @ 241000000 );', 'Pengadaan Media Publikasi/Presentasi Kegiatan UPLAND dilaksanakan dalam 2 (dua) paket pekerjaan dengan nilai sebesar Rp241.000.000 per paket. Kegiatan ini bertujuan untuk mendukung penyebarluasan informasi, dokumentasi capaian program, serta penyajian materi kegiatan secara informatif, menarik, dan profesional kepada para pemangku kepentingan. Ruang lingkup pekerjaan meliputi perencanaan konsep komunikasi, produksi materi publikasi (seperti video dokumenter, video profil, infografis, leaflet, booklet, banner, atau materi digital lainnya), penyusunan bahan presentasi, serta dokumentasi kegiatan (foto dan video). Termasuk di dalamnya proses editing, desain grafis, layout, pengemasan konten, serta distribusi/publikasi melalui media yang disepakati. Seluruh produk media harus memenuhi standar kualitas visual dan substansi, memuat identitas program secara jelas, serta sesuai dengan pedoman komunikasi dan ketentuan yang berlaku. Penyedia wajib menyerahkan seluruh output dalam format cetak dan/atau digital sesuai kebutuhan program.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526802);
