INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094047', 66094047, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND (2 kali x 35 orang)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 42000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 70, OH, @ 600000 )', '1. Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND (2 kali x 35 orang) ( 70, OH, @ 600000 );', 'Pertemuan koordinasi, pembinaan, monitoring, evaluasi, dan sinkronisasi kegiatan UPLAND dilaksanakan sebagai bagian dari upaya untuk memastikan pelaksanaan program berjalan secara efektif, terkoordinasi, dan sesuai dengan rencana yang telah ditetapkan. Kegiatan ini bertujuan untuk memperkuat koordinasi antar pihak terkait, melakukan pembinaan kepada pelaksana kegiatan di lapangan, serta melakukan pemantauan dan evaluasi terhadap perkembangan pelaksanaan program UPLAND. Kegiatan ini direncanakan dilaksanakan sebanyak 2 (dua) kali pertemuan dengan jumlah peserta 35 orang pada setiap pertemuan, sehingga total pelaksanaan kegiatan sebesar 70 Orang Hari (OH). Peserta kegiatan terdiri dari unsur pengelola program, tim teknis, pendamping lapangan, serta pihak terkait lainnya yang memiliki peran dalam pelaksanaan dan pengendalian kegiatan program UPLAND. Dalam kegiatan ini akan dilakukan pembahasan mengenai perkembangan pelaksanaan kegiatan program, capaian target yang telah direncanakan, kendala atau permasalahan yang dihadapi di lapangan, serta langkah-langkah strategis yang perlu dilakukan untuk meningkatkan efektivitas pelaksanaan program. Selain itu, kegiatan ini juga dimanfaatkan untuk melakukan sinkronisasi kegiatan antar unit kerja maupun dengan pihak terkait lainnya agar pelaksanaan program dapat berjalan secara terpadu dan selaras dengan kebijakan serta rencana kerja yang telah ditetapkan. Pelaksanaan kegiatan difasilitasi melalui penyediaan paket meeting yang mencakup ruang pertemuan yang representatif, peralatan presentasi seperti LCD proyektor, layar, sound system, meja dan kursi pertemuan, serta perlengkapan pendukung lainnya yang diperlukan selama kegiatan berlangsung. Selain itu, paket meeting juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung sesuai dengan standar pelaksanaan kegiatan rapat atau pertemuan. Melalui pelaksanaan kegiatan ini diharapkan tercipta koordinasi yang lebih baik antar pihak terkait, peningkatan pemahaman pelaksana kegiatan terhadap pelaksanaan program, serta tersusunnya rekomendasi perbaikan yang dapat digunakan sebagai bahan dalam pengambilan keputusan dan penyempurnaan pelaksanaan program UPLAND ke depan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526847);
