INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094054', 66094054, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket meeting dalam rangka Monitoring dan Evaluasi', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 160000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 200, OH, @ 800000 )', '1. Paket meeting dalam rangka Monitoring dan Evaluasi ( 200, OH, @ 800000 );', 'Paket meeting dalam rangka kegiatan monitoring dan evaluasi dilaksanakan untuk mendukung pelaksanaan pertemuan yang bertujuan melakukan pemantauan terhadap pelaksanaan kegiatan program, menilai capaian kinerja, serta mengidentifikasi berbagai permasalahan yang muncul selama proses pelaksanaan kegiatan. Selain itu, kegiatan ini juga dimaksudkan untuk melakukan evaluasi terhadap hasil yang telah dicapai sehingga dapat menjadi bahan perbaikan dan penyempurnaan pelaksanaan program ke depan. Kegiatan ini dilaksanakan dengan total 200 Orang Hari (OH) yang melibatkan unsur pengelola program, tim teknis, pelaksana kegiatan di lapangan, serta pihak terkait lainnya yang memiliki peran dalam pelaksanaan dan pengawasan kegiatan program. Melalui pertemuan ini, para peserta dapat melakukan pembahasan mengenai perkembangan kegiatan, pencapaian target, kendala yang dihadapi, serta langkah-langkah strategis yang perlu dilakukan untuk meningkatkan efektivitas pelaksanaan program. Pelaksanaan kegiatan difasilitasi melalui paket meeting yang menyediakan sarana dan prasarana pertemuan yang memadai. Fasilitas yang disediakan meliputi ruang pertemuan yang representatif, peralatan presentasi seperti LCD proyektor, layar, sound system, meja dan kursi rapat, serta perlengkapan penunjang lainnya yang diperlukan selama kegiatan berlangsung. Selain penyediaan fasilitas ruang pertemuan dan perlengkapan rapat, paket meeting juga mencakup konsumsi bagi peserta selama kegiatan berlangsung, seperti makan dan coffee break sesuai dengan standar pelaksanaan kegiatan rapat atau pertemuan. Penyediaan fasilitas tersebut bertujuan untuk menunjang kenyamanan peserta sehingga kegiatan monitoring dan evaluasi dapat berlangsung secara efektif dan produktif. Melalui kegiatan monitoring dan evaluasi ini diharapkan dapat diperoleh gambaran yang komprehensif mengenai pelaksanaan kegiatan program, tingkat pencapaian target yang telah ditetapkan, serta rekomendasi langkah-langkah perbaikan yang diperlukan. Hasil dari kegiatan ini selanjutnya dapat menjadi bahan pertimbangan dalam pengambilan keputusan serta penyempurnaan pelaksanaan kegiatan program pada periode berikutnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526857);
