INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094008', 66094008, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsumsi Rapat dalam Kantor', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 17500000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 350, OK, @ 50000 )', '1. Konsumsi Rapat dalam Kantor ( 350, OK, @ 50000 );', 'Konsumsi rapat dalam kantor merupakan penyediaan makanan dan minuman ringan yang diperuntukkan bagi peserta rapat atau pertemuan yang dilaksanakan di lingkungan kantor dalam rangka mendukung kelancaran koordinasi dan pelaksanaan kegiatan program. Kegiatan ini dialokasikan sebanyak 350 Orang Konsumsi (OK) dengan satuan biaya sebesar Rp50.000 per orang. Penyediaan konsumsi rapat bertujuan untuk menunjang pelaksanaan berbagai kegiatan rapat, seperti rapat koordinasi, rapat teknis, pembahasan program, evaluasi kegiatan, serta pertemuan internal tim pelaksana yang dilakukan dalam rangka mendukung pelaksanaan program. Konsumsi yang disediakan umumnya berupa makanan ringan/snack dan minuman, yang disesuaikan dengan standar konsumsi rapat dalam kantor serta memperhatikan aspek kebersihan, kualitas, dan kelayakan konsumsi. Konsumsi rapat disediakan sesuai dengan jumlah peserta yang hadir dalam setiap kegiatan rapat dan didistribusikan selama kegiatan berlangsung. Penyediaan konsumsi ini diharapkan dapat menciptakan suasana rapat yang lebih kondusif serta mendukung efektivitas diskusi, koordinasi, dan pengambilan keputusan dalam pelaksanaan kegiatan program. Dengan adanya dukungan konsumsi rapat dalam kantor, pelaksanaan kegiatan rapat dan koordinasi internal dapat berjalan dengan lebih tertib, efektif, dan produktif, sehingga mendukung kelancaran pelaksanaan tugas dan pencapaian target kegiatan yang telah direncanakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526873);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093964', 66093964, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Tenaga Administrasi PMU Pusat', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 720000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 120, OB, @ 6000000 )', '1. Tenaga Administrasi PMU Pusat ( 120, OB, @ 6000000 );', 'Pengadaan Tenaga Administrasi PMU Pusat dilaksanakan selama 120 (seratus dua puluh) orang bulan (OB) dengan besaran honorarium Rp6.000.000 per orang bulan. Tenaga administrasi bertugas mendukung kelancaran operasional dan tata kelola administrasi program pada tingkat pusat secara efektif dan akuntabel. Ruang lingkup pekerjaan meliputi pengelolaan surat-menyurat, pengarsipan dokumen fisik dan digital, penyusunan dan rekapitulasi laporan administrasi, dukungan administrasi kegiatan rapat/koordinasi, pengelolaan jadwal dan dokumen perjalanan dinas, serta membantu proses administrasi keuangan sesuai ketentuan yang berlaku. Pelaksanaan tugas harus menjamin ketertiban administrasi, ketepatan waktu, kerapian dokumentasi, serta menjaga kerahasiaan dokumen program sesuai standar operasional dan peraturan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526874);
