INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093947', 66093947, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Pengelolaan dan Perawatan Alsintan', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 144000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 180, Pkt, @ 800000 )', '1. Paket Meeting Pengelolaan dan Perawatan Alsintan ( 180, Pkt, @ 800000 );', 'Paket meeting pengelolaan dan perawatan alat dan mesin pertanian (alsintan) dilaksanakan sebagai bagian dari upaya peningkatan kapasitas sumber daya manusia dalam mendukung pemanfaatan alsintan secara optimal, efisien, dan berkelanjutan. Kegiatan ini bertujuan untuk memberikan pemahaman dan keterampilan kepada peserta mengenai tata cara penggunaan, pengelolaan, serta perawatan alsintan agar dapat berfungsi dengan baik dan memiliki umur pakai yang lebih panjang. Kegiatan ini dilaksanakan dengan total 180 paket pertemuan yang melibatkan peserta dari unsur petani, kelompok tani, pengelola kelembagaan petani, penyuluh pertanian, serta pihak terkait lainnya yang memiliki peran dalam pemanfaatan dan pengelolaan alsintan di lapangan. Melalui kegiatan ini, peserta akan memperoleh materi mengenai jenis-jenis alsintan, tata cara pengoperasian yang benar, pemeliharaan rutin, serta penanganan awal apabila terjadi kerusakan pada peralatan. Pelaksanaan kegiatan difasilitasi melalui paket meeting yang menyediakan sarana dan prasarana yang memadai untuk mendukung proses pelatihan dan diskusi. Fasilitas yang disediakan meliputi ruang pertemuan yang representatif, peralatan presentasi seperti LCD proyektor, layar, sound system, meja dan kursi pertemuan, serta perlengkapan pendukung lainnya yang diperlukan selama kegiatan berlangsung. Selain fasilitas ruang pertemuan dan perlengkapan kegiatan, paket meeting juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung, seperti makan dan coffee break sesuai dengan standar pelaksanaan kegiatan rapat atau pelatihan. Penyediaan fasilitas ini bertujuan untuk menunjang kenyamanan peserta sehingga kegiatan dapat berlangsung dengan efektif. Melalui kegiatan ini diharapkan peserta memiliki pemahaman yang lebih baik mengenai pengelolaan dan perawatan alsintan sehingga peralatan yang tersedia dapat dimanfaatkan secara optimal dalam mendukung kegiatan usaha tani. Dengan demikian, kegiatan ini diharapkan dapat berkontribusi terhadap peningkatan produktivitas pertanian serta mendukung keberlanjutan pemanfaatan alsintan di tingkat petani dan kelembagaan pertanian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526896);
