INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094044', 66094044, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND (2 kali x 35 orang)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 42000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 70, OH, @ 600000 )', '1. Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND (2 kali x 35 orang) ( 70, OH, @ 600000 );', 'Kegiatan pertemuan koordinasi, pembinaan, monitoring, evaluasi, dan sinkronisasi Program UPLAND dilaksanakan sebagai sarana untuk memperkuat koordinasi antar pemangku kepentingan, meningkatkan efektivitas pelaksanaan program, serta memastikan keselarasan antara perencanaan dan pelaksanaan kegiatan di lapangan. Pertemuan ini bertujuan untuk menyamakan persepsi, menyampaikan perkembangan pelaksanaan program, mengidentifikasi kendala yang dihadapi, serta merumuskan langkah-langkah perbaikan dan tindak lanjut guna meningkatkan kualitas pelaksanaan kegiatan. Kegiatan ini diikuti oleh unsur pelaksana program, perwakilan instansi terkait, tim teknis, serta pihak-pihak lain yang memiliki keterkaitan dengan pelaksanaan Program UPLAND. Peserta yang hadir diharapkan dapat memberikan masukan, berbagi pengalaman pelaksanaan kegiatan di lapangan, serta berkontribusi dalam proses evaluasi dan penyusunan rencana tindak lanjut program. Pelaksanaan kegiatan dilakukan dalam bentuk pertemuan resmi yang difasilitasi dengan sarana dan prasarana pendukung yang memadai. Fasilitas yang disediakan meliputi ruang pertemuan yang representatif, perlengkapan presentasi seperti LCD proyektor, layar proyeksi, sound system, serta perlengkapan administrasi pertemuan. Selain itu, peserta juga memperoleh bahan pertemuan berupa materi paparan, dokumen pendukung, serta alat tulis yang diperlukan selama kegiatan berlangsung. Materi yang dibahas dalam kegiatan ini meliputi penyampaian kebijakan dan arah pelaksanaan Program UPLAND, laporan perkembangan kegiatan, pembinaan teknis kepada pelaksana di lapangan, pembahasan hasil monitoring, serta evaluasi terhadap capaian kegiatan yang telah dilaksanakan. Selain itu, dilakukan pula diskusi dan sesi tanya jawab untuk menggali berbagai permasalahan yang muncul di lapangan serta mencari solusi yang dapat diterapkan secara bersama. Hasil dari kegiatan pertemuan ini diharapkan berupa rumusan kesepakatan bersama, rekomendasi perbaikan pelaksanaan program, serta rencana tindak lanjut yang akan dilaksanakan oleh masing-masing pihak terkait. Seluruh hasil pembahasan akan didokumentasikan dalam bentuk notulen atau laporan kegiatan sebagai bahan evaluasi dan acuan dalam pelaksanaan kegiatan selanjutnya. Dengan dilaksanakannya kegiatan pertemuan koordinasi, pembinaan, monitoring, evaluasi, dan sinkronisasi ini, diharapkan pelaksanaan Program UPLAND dapat berjalan lebih efektif, terkoordinasi dengan baik, serta mampu mencapai tujuan dan sasaran program secara optimal', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526911);
