INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093958', 66093958, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsultan Individu Bidang Community Development', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 200000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 10, OB, @ 20000000 )', '1. Konsultan Individu Bidang Community Development ( 10, OB, @ 20000000 );', 'Pengadaan Konsultan Individu Bidang Community Development dilaksanakan selama 10 (sepuluh) orang bulan (OB) dengan besaran honorarium Rp20.000.000 per orang bulan. Konsultan bertugas memberikan dukungan teknis dalam perencanaan, pelaksanaan, pendampingan, serta penguatan kapasitas masyarakat dalam rangka mendukung keberhasilan program. Ruang lingkup pekerjaan meliputi penyusunan strategi pemberdayaan masyarakat, fasilitasi pembentukan dan penguatan kelembagaan kelompok, pendampingan kegiatan di tingkat lapangan, peningkatan partisipasi masyarakat, serta koordinasi dengan pemangku kepentingan terkait. Konsultan juga bertanggung jawab melakukan monitoring dan evaluasi kegiatan pemberdayaan serta menyusun laporan berkala dan laporan akhir. Pelaksanaan tugas harus menghasilkan output yang terukur, terdokumentasi dengan baik, dan sesuai dengan kerangka kerja serta ketentuan program yang berlaku', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526951);
