INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093949', 66093949, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Sewa kendaraan Operasional Kantor R4 (DPIU)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 1176000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 0, '( 14, Unit, @ 84000000 )', '1. Sewa kendaraan Operasional Kantor R4 (DPIU) ( 14, Unit, @ 84000000 );', 'Pengadaan sewa kendaraan operasional kantor roda 4 (R4) untuk DPIU dilaksanakan sebanyak 14 (empat belas) unit kendaraan selama periode kontrak, dengan nilai sebesar Rp84.000.000 per unit. Kendaraan digunakan untuk mendukung pelaksanaan kegiatan operasional di tingkat daerah, termasuk koordinasi, monitoring, pembinaan, supervisi lapangan, serta kegiatan teknis lainnya dalam rangka pelaksanaan program. Kendaraan yang disediakan harus dalam kondisi prima dan laik jalan, memiliki dokumen kendaraan lengkap dan aktif (STNK), serta dilengkapi asuransi sesuai ketentuan yang berlaku. Spesifikasi minimal kendaraan berupa tipe penumpang/minibus atau setara, kapasitas memadai, kondisi mesin dan interior baik, serta memenuhi standar keselamatan. Biaya sewa mencakup penggunaan kendaraan selama masa kontrak termasuk pajak kendaraan dan perawatan rutin, sesuai perjanjian kerja sama. Penyedia wajib menjamin ketersediaan kendaraan secara berkelanjutan untuk menunjang efektivitas dan kelancaran operasional DPIU.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2526981);
