INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094920', 66094920, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Belanja Sewa', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 85000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1. Sewa Mobil ( 85, Hari, @ 1000000 );', '1. Sewa Mobil ( 85, Hari, @ 1000000 );', 'Kegiatan sewa mobil insidentil dilaksanakan untuk mendukung pelaksanaan evaluasi kegiatan Operasi dan Pemeliharaan (OP) Jaringan Irigasi Tersier di lokasi sasaran. Evaluasi dilakukan guna menilai tingkat pencapaian pelaksanaan kegiatan, kesesuaian dengan rencana kerja, kondisi fisik jaringan irigasi, serta efektivitas pengelolaan dan pemanfaatan anggaran. Mengingat lokasi jaringan irigasi tersier tersebar di berbagai wilayah dan sebagian berada di area persawahan atau lokasi dengan akses terbatas, diperlukan dukungan sarana transportasi yang fleksibel dan siap digunakan sesuai kebutuhan penugasan. Kendaraan sewa digunakan oleh tim teknis untuk melakukan peninjauan lapangan, verifikasi hasil pekerjaan, pengumpulan data dan dokumentasi, serta koordinasi dengan pengelola irigasi di tingkat daerah maupun kelompok tani pengelola jaringan tersier. Kendaraan yang disediakan berupa kendaraan roda empat jenis MPV/minibus atau setara dalam kondisi laik jalan, terawat, serta dilengkapi dokumen kendaraan yang sah dan masih berlaku. Layanan sewa termasuk pengemudi yang memiliki SIM A aktif, berpengalaman, dan memahami wilayah penugasan guna mendukung kelancaran mobilitas tim evaluasi. Pelaksanaan sewa dilakukan secara harian sesuai kebutuhan kegiatan evaluasi lapangan. Pembayaran dilaksanakan berdasarkan jumlah hari pemakaian riil yang dibuktikan dengan surat tugas dan berita acara penggunaan kendaraan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527013);
