INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093975', 66093975, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Belanja Jasa Lainnya', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 1410000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '1 Paket', '1. Village Fasilitator 23 Desa ( 276, OB, @ 4000000 ); 2. Manager Village Facilitator ( 12, OB, @ 10000000 ); 3. Petugas On Granting IFAD ( 12, OB, @ 4000000 ); 4. Petugas On Granting ISDB ( 12, OB, @ 4000000 ); 5. Media Publikasi /Video Dokumentasi ( 1, Pkt, @ 50000000 ); 6. Tenaga Administrasi Keuangan ( 10, OB, @ 4000000 );', '1. Village Facilitator 23 Desa (276 OB @ Rp4.000.000) Pengadaan Village Facilitator untuk 23 desa dilaksanakan selama 276 (dua ratus tujuh puluh enam) orang bulan (OB) dengan honorarium Rp4.000.000 per orang bulan. Fasilitator bertugas melakukan pendampingan langsung kepada masyarakat desa dalam perencanaan, pelaksanaan, serta monitoring kegiatan program. Ruang lingkup pekerjaan meliputi fasilitasi musyawarah desa, penguatan kelembagaan kelompok, pendampingan pelaksanaan kegiatan di tingkat desa, serta penyusunan laporan perkembangan kegiatan secara berkala. Fasilitator bertanggung jawab memastikan partisipasi aktif masyarakat dan kelancaran implementasi program di desa dampingan. 2. Manager Village Facilitator (12 OB @ Rp10.000.000) Pengadaan Manager Village Facilitator dilaksanakan selama 12 (dua belas) OB dengan honorarium Rp10.000.000 per orang bulan. Manager bertugas mengoordinasikan, mengendalikan, dan mengevaluasi kinerja para Village Facilitator agar pelaksanaan kegiatan di tingkat desa berjalan efektif dan sesuai target. Ruang lingkup meliputi penyusunan rencana kerja, supervisi lapangan, konsolidasi laporan, serta koordinasi dengan tim manajemen program dan pemangku kepentingan terkait. 3. Petugas On Granting IFAD (12 OB @ Rp4.000.000) Pengadaan Petugas On Granting IFAD dilaksanakan selama 12 OB dengan honorarium Rp4.000.000 per orang bulan. Petugas bertanggung jawab mendukung pengelolaan administrasi dan pelaporan dana on granting yang bersumber dari IFAD sesuai ketentuan yang berlaku. Tugas meliputi verifikasi dokumen, pencatatan administrasi, monitoring penyaluran dan penggunaan dana, serta penyusunan laporan keuangan dan kemajuan kegiatan sesuai pedoman pembiayaan. 4. Petugas On Granting ISDB (12 OB @ Rp4.000.000) Pengadaan Petugas On Granting ISDB dilaksanakan selama 12 OB dengan honorarium Rp4.000.000 per orang bulan. Petugas bertugas mengelola administrasi dan pelaporan dana on granting yang bersumber dari ISDB sesuai ketentuan pembiayaan yang berlaku. Ruang lingkup pekerjaan meliputi verifikasi dokumen pendukung, pencatatan transaksi, monitoring penggunaan dana, serta penyusunan laporan secara berkala sesuai standar yang ditetapkan. 5. Media Publikasi / Video Dokumentasi (1 Paket @ Rp50.000.000) Pengadaan Media Publikasi/Video Dokumentasi dilaksanakan dalam 1 paket pekerjaan dengan nilai Rp50.000.000 untuk mendukung dokumentasi dan diseminasi capaian program. Ruang lingkup meliputi penyusunan konsep, pengambilan gambar/foto kegiatan, produksi dan editing video dokumenter, penyusunan narasi, serta penyediaan hasil akhir dalam format digital siap tayang. Produk yang dihasilkan harus berkualitas baik, informatif, dan mencerminkan capaian program secara profesional. 6. Tenaga Administrasi Keuangan (10 OB @ Rp4.000.000) Pengadaan Tenaga Administrasi Keuangan dilaksanakan selama 10 OB dengan honorarium Rp4.000.000 per orang bulan. Tenaga ini bertugas mendukung pengelolaan administrasi keuangan program agar tertib, akuntabel, dan sesuai ketentuan. Ruang lingkup pekerjaan meliputi pencatatan transaksi, pengarsipan dokumen keuangan, penyusunan rekapitulasi dan laporan keuangan, serta membantu proses verifikasi administrasi sesuai standar operasional dan peraturan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527076);
