INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093973', 66093973, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Site Enginer', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 980000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 56, OB, @ 17500000 )', '1. Site Enginer ( 56, OB, @ 17500000 );', 'Pengadaan tenaga Site Engineer dilaksanakan selama 56 (lima puluh enam) orang bulan (OB) dengan besaran honorarium Rp17.500.000 per orang bulan. Site Engineer bertugas memberikan dukungan teknis dalam pengawasan dan pengendalian pelaksanaan pekerjaan fisik di lapangan agar sesuai dengan desain, spesifikasi teknis, mutu, waktu, dan biaya yang telah ditetapkan. Ruang lingkup pekerjaan meliputi pemeriksaan gambar kerja dan spesifikasi teknis, pengawasan kualitas material dan metode pelaksanaan, pengukuran dan verifikasi volume pekerjaan, identifikasi serta penanganan permasalahan teknis di lapangan, serta koordinasi dengan kontraktor, konsultan, dan pihak terkait lainnya. Site Engineer juga bertanggung jawab menyusun laporan harian/mingguan/bulanan serta memberikan rekomendasi teknis apabila terjadi deviasi pekerjaan. Pelaksanaan tugas harus menjamin mutu pekerjaan sesuai standar teknis yang berlaku, keselamatan kerja di lokasi proyek, serta ketertiban administrasi pelaporan sesuai ketentuan kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527093);
