INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093994', 66093994, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsultan Knowladge management', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 160000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 10, OB, @ 16000000 )', '1. Konsultan Knowladge management ( 10, OB, @ 16000000 );', 'Pengadaan Konsultan Knowledge Management dilaksanakan selama 10 (sepuluh) orang bulan (OB) dengan besaran honorarium Rp16.000.000 per orang bulan. Konsultan bertugas mendukung pengelolaan pengetahuan (knowledge management) program agar informasi, pengalaman, dan pembelajaran dari pelaksanaan kegiatan dapat terdokumentasi dengan baik serta dimanfaatkan untuk peningkatan kualitas program. Ruang lingkup pekerjaan meliputi pengumpulan dan pengolahan data serta praktik baik (best practices) dari kegiatan program, penyusunan sistem dokumentasi pengetahuan, pengembangan materi pembelajaran dan publikasi, serta fasilitasi proses berbagi pengetahuan antar pemangku kepentingan. Konsultan juga bertanggung jawab menyusun laporan hasil pengelolaan pengetahuan dan rekomendasi pengembangan program ke depan. Pelaksanaan tugas harus menghasilkan dokumentasi pengetahuan yang sistematis, mudah diakses, serta mendukung diseminasi informasi dan pembelajaran program secara efektif.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527134);
