INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094018', 66094018, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Kegiatan dalam rangka koordinasi, perencanaan, Sosialisasi, dll', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 180000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 200, OH, @ 900000 )', '1. Paket Meeting Kegiatan dalam rangka koordinasi, perencanaan, Sosialisasi, dll ( 200, OH, @ 900000 );', 'Paket Meeting Kegiatan dalam rangka koordinasi, perencanaan, sosialisasi, dan kegiatan sejenis merupakan penyediaan layanan pertemuan untuk mendukung pelaksanaan kegiatan program agar dapat berjalan secara efektif dan terkoordinasi dengan baik. Kegiatan ini bertujuan untuk memfasilitasi komunikasi, penyampaian informasi, pembahasan rencana kerja, serta sosialisasi kebijakan atau program kepada para pemangku kepentingan terkait. Paket meeting ini mencakup penyediaan ruang pertemuan yang memadai sesuai dengan jumlah peserta, serta dilengkapi dengan fasilitas pendukung seperti meja dan kursi, pendingin ruangan, LCD projector, layar presentasi, sound system, microphone, dan fasilitas lainnya yang diperlukan untuk menunjang kelancaran kegiatan. Selain itu, paket ini juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung, seperti makan dan coffee break sesuai dengan standar layanan pertemuan. Dengan tersedianya paket meeting ini, diharapkan kegiatan koordinasi, perencanaan, sosialisasi, dan kegiatan lainnya dapat terlaksana secara tertib, efektif, dan menghasilkan kesepahaman serta tindak lanjut yang mendukung pelaksanaan program.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527207);
