INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094002', 66094002, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'ATK', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 6000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 12, BLN, @ 500000 )', '1. ATK ( 12, BLN, @ 500000 );', 'Penyediaan Alat Tulis Kantor (ATK) merupakan bagian dari dukungan operasional kegiatan dalam rangka Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND. Kebutuhan ATK dialokasikan selama 12 bulan dengan satuan biaya Rp500.000 per bulan, yang digunakan untuk menunjang kelancaran administrasi, dokumentasi, serta pelaksanaan kegiatan perkantoran yang berkaitan dengan program tersebut. ATK yang disediakan meliputi berbagai perlengkapan tulis dan kebutuhan administrasi kantor yang digunakan dalam proses penyusunan dokumen, pencatatan hasil rapat, pengarsipan, serta kegiatan koordinasi program. Jenis perlengkapan yang termasuk dalam ATK antara lain kertas HVS berbagai ukuran, pulpen, pensil, spidol, stabilo, buku catatan, map folder, ordner, sticky notes, amplop, paper clip, binder clip, serta perlengkapan pendukung lainnya yang diperlukan dalam kegiatan administrasi program. Penggunaan ATK ini dimaksudkan untuk mendukung berbagai aktivitas kerja seperti penyusunan laporan kegiatan, pencatatan hasil diskusi atau rapat koordinasi, pengelolaan dokumen program, serta kebutuhan administrasi lainnya yang berkaitan dengan pelaksanaan kegiatan UPLAND. Penyediaan ATK juga memastikan bahwa seluruh proses dokumentasi dan pengelolaan data kegiatan dapat dilakukan secara tertib, rapi, dan sistematis. Pengadaan ATK dilakukan secara bertahap sesuai dengan kebutuhan operasional selama periode kegiatan berlangsung, sehingga ketersediaan perlengkapan kantor tetap terjaga dan dapat dimanfaatkan secara optimal oleh tim pelaksana kegiatan. Dengan adanya dukungan ATK yang memadai, diharapkan seluruh kegiatan administrasi dan pelaporan dalam rangka pelaksanaan Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND dapat berjalan dengan lancar, efektif, dan akuntabel.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527364);
