INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094907', 66094907, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Belanja Sewa', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 86000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, 'Sewa mobil ( 86, HARI, @ 1000000 )', '1. Sewa mobil ( 86, HARI, @ 1000000 );', 'Mengingat lokasi jaringan irigasi tersier tersebar di berbagai wilayah dan sebagian berada di area persawahan atau lokasi yang sulit dijangkau, diperlukan dukungan sarana transportasi yang fleksibel dan siap digunakan sesuai kebutuhan penugasan. Volume sewa mobil direncanakan sebanyak 86 (delapan puluh enam) hari dengan harga satuan Rp1.000.000,- (satu juta rupiah) per hari, sehingga total anggaran sebesar Rp86.000.000,- (delapan puluh enam juta rupiah). Sistem sewa dilaksanakan secara harian sesuai kebutuhan operasional lapangan. Kendaraan yang disediakan berupa kendaraan roda empat jenis MPV/minibus atau setara dalam kondisi laik jalan, terawat, serta dilengkapi dokumen kendaraan yang sah dan masih berlaku. Layanan sewa termasuk pengemudi yang memiliki SIM A aktif dan memahami wilayah penugasan guna mendukung kelancaran mobilitas tim. Pembayaran dilakukan berdasarkan jumlah hari pemakaian riil yang dibuktikan dengan surat tugas dan berita acara penggunaan kendaraan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527487);
