INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66091716', 66091716, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Tenaga Pendukung Penyusunan Laporan Pengadministrasian  Dokumen Analisis Keuangan dan Perpajakan', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 90298350, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 Bulan', 'Sasaran kerja dari Tenaga Pendukung Penyusunan Laporan Pengadministrasian Dokumen Analisis Keuangan dan Perpajakan adalah untuk mendukung kelancaran pelaksanaan tugas di unit kerja Direktorat Sinergi dan Tata Kelola Perencanaan Pembangunan, yang meliputi: 1. Terselenggaranya dukungan administrasi keuangan yang efektif, akuntabel, dan sesuai aturan, sehingga seluruh proses keuangan Direktorat dapat berjalan lancar dan mendukung pelaksanaan agenda penyusunan RKP; 2. Tersedianya dokumen keuangan yang lengkap, valid, dan terstandarisasi, termasuk LPJ serta laporan realisasi anggaran yang menjadi dasar pertanggungjawaban keuangan yang kredibel; 3. Tercapainya ketepatan waktu penyusunan LPJ dan laporan realisasi, yang berdampak langsung pada kelancaran pelaksanaan kegiatan Direktorat; 4. Terlaksananya pengelolaan arsip keuangan berbasis digital secara tertib melalui SharePoint, yang mempermudah proses kontrol internal, audit, serta akses dokumen oleh unit terkait.', 'Ruang lingkup kerja Tenaga Pendukung Penyusunan Laporan Pengadministrasian Dokumen Analisis Keuangan dan Perpajakan adalah sebagai berikut: 1. Penyiapan Dokumen Perencanaan dan Pelaksanaan Anggaran; 2. Penyusunan Laporan Keuangan Berkala; 3. Penyusunan laporan pertanggungjawaban (LPJ) kegiatan secara komprehensif sesuai pedoman Kementerian PPN/Bappenas dan peraturan perbendaharaan; 4. Penyiapan Dokumen Dukungan Teknis Administrasi Pembayaran; 5. Melaksanakan tugas lainnya sesuai permintaan Pimpinan Tim dan/atau Bappenas;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527557);
