INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094917', 66094917, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Belanja Sewa', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 77000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1. Sewa mobil ( 77, HARI, @ 1000000 );', '1. Sewa mobil ( 77, HARI, @ 1000000 );', 'Kegiatan sewa mobil insidentil dilaksanakan untuk mendukung pelaksanaan pendampingan dan pengawalan kegiatan Operasi dan Pemeliharaan (OP) Jaringan Irigasi Tersier. Pendampingan dan pengawalan dilakukan guna memastikan kegiatan OP berjalan sesuai ketentuan teknis, tepat sasaran, serta terdokumentasi secara tertib dan akuntabel. Mengingat lokasi jaringan irigasi tersier tersebar di berbagai wilayah dan sebagian berada pada area persawahan atau lokasi yang memerlukan akses khusus, diperlukan dukungan sarana transportasi yang fleksibel dan siap digunakan sesuai kebutuhan penugasan. Kendaraan sewa digunakan oleh tim teknis untuk melakukan monitoring lapangan, verifikasi kondisi jaringan, pembinaan kepada pengelola irigasi tersier, serta koordinasi dengan unit kerja dan pemerintah daerah setempat. Kendaraan yang disediakan berupa kendaraan roda empat jenis MPV/minibus atau setara dalam kondisi laik jalan, terawat, serta dilengkapi dokumen kendaraan yang sah dan masih berlaku. Layanan sewa termasuk pengemudi yang memiliki SIM A aktif dan memahami wilayah penugasan sehingga dapat menunjang mobilitas tim secara efektif. Pelaksanaan sewa dilakukan secara harian sesuai kebutuhan kegiatan pendampingan dan 