INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094004', 66094004, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Pelatihan Budidaya Komoditas', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 144000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 180, Pkt, @ 800000 )', '1. Paket Meeting Pelatihan Budidaya Komoditas ( 180, Pkt, @ 800000 );', 'Paket meeting pelatihan budidaya komoditas merupakan layanan penyelenggaraan kegiatan pelatihan yang disediakan oleh penyedia jasa pertemuan, seperti hotel, balai pelatihan, atau tempat pertemuan lainnya yang memiliki fasilitas memadai untuk mendukung kegiatan pelatihan. Paket ini bertujuan untuk menunjang kelancaran pelaksanaan kegiatan pelatihan budidaya komoditas bagi peserta, sehingga proses penyampaian materi, diskusi, dan praktik pembelajaran dapat berlangsung secara efektif dan kondusif. Paket meeting pelatihan mencakup penyediaan ruang pertemuan atau ruang pelatihan yang representatif dengan kapasitas yang disesuaikan dengan jumlah peserta kegiatan. Ruangan tersebut dilengkapi dengan fasilitas pendukung pelatihan seperti meja dan kursi sesuai dengan tata letak pelatihan (classroom atau kelompok), LCD proyektor, layar proyektor, sound system, microphone, papan tulis atau flipchart, serta akses listrik dan jaringan internet guna mendukung kegiatan presentasi materi, diskusi, dan penyampaian informasi selama pelatihan berlangsung. Selain penyediaan ruang pelatihan, paket meeting juga mencakup konsumsi bagi peserta selama kegiatan berlangsung, yang umumnya terdiri dari makan siang dan dua kali coffee break setiap hari pelaksanaan kegiatan. Konsumsi disediakan oleh pihak penyedia jasa dengan memperhatikan standar kebersihan, kualitas makanan, serta kecukupan gizi bagi peserta pelatihan. Paket ini juga dapat mencakup fasilitas pendukung kegiatan, seperti penyediaan alat tulis peserta (blocknote, pulpen, dan map pelatihan), air minum, serta layanan teknis dari petugas tempat kegiatan yang membantu dalam penyiapan ruang, pengoperasian peralatan presentasi, dan memastikan kegiatan pelatihan dapat berjalan dengan tertib dan lancar. Dengan adanya paket meeting pelatihan ini, diharapkan seluruh rangkaian kegiatan pelatihan budidaya komoditas dapat terlaksana secara optimal, mulai dari penyampaian materi oleh narasumber, diskusi interaktif dengan peserta, hingga proses pembelajaran yang bertujuan untuk meningkatkan pengetahuan, keterampilan, dan kapasitas peserta dalam penerapan teknik budidaya komoditas yang baik dan berkelanjutan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527661);
