INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093946', 66093946, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Pelatihan OM  SECAP', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 240000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 300, OH, @ 800000 )', '1. Paket Meeting Pelatihan OM SECAP ( 300, OH, @ 800000 );', 'Paket Meeting Pelatihan OM SECAP merupakan penyediaan layanan pertemuan yang digunakan untuk mendukung pelaksanaan kegiatan pelatihan dalam rangka peningkatan kapasitas terkait Operation and Maintenance (OM) serta penerapan pendekatan SECAP pada kegiatan program. Paket ini disediakan untuk memastikan kegiatan pelatihan dapat berlangsung secara efektif, tertib, dan sesuai dengan kebutuhan peserta serta penyelenggara kegiatan. Paket meeting ini mencakup penyediaan ruang pertemuan yang representatif dan memadai untuk pelaksanaan kegiatan pelatihan, termasuk fasilitas pendukung seperti meja, kursi, pendingin ruangan, serta perlengkapan presentasi seperti LCD projector, layar, sound system, dan fasilitas lainnya yang diperlukan untuk menunjang proses penyampaian materi pelatihan. Selain itu, paket meeting juga mencakup penyediaan konsumsi bagi peserta kegiatan selama pelaksanaan pelatihan, seperti makan siang dan coffee break sesuai dengan standar pelayanan kegiatan pertemuan. Penyedia layanan juga diharapkan memastikan kenyamanan dan kelancaran kegiatan pelatihan melalui dukungan layanan teknis selama kegiatan berlangsung. Kegiatan Pelatihan OM SECAP ini bertujuan untuk meningkatkan pemahaman, pengetahuan, dan kapasitas peserta terkait pengelolaan operasional dan pemeliharaan kegiatan program secara berkelanjutan, sehingga hasil kegiatan program dapat dimanfaatkan secara optimal dan berkelanjutan oleh para pemangku kepentingan di tingkat lapangan. Pelaksanaan paket meeting ini diharapkan mampu mendukung terselenggaranya kegiatan pelatihan secara efektif, interaktif, dan kondusif sehingga tujuan kegiatan pelatihan dapat tercapai dengan baik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527702);
