INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093966', 66093966, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsultan Individu Bidang Agronomis', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 200000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 10, OB, @ 20000000 )', '1. Konsultan Individu Bidang Agronomis ( 10, OB, @ 20000000 );', 'Pengadaan Konsultan Individu Bidang Agronomis dilaksanakan selama 10 (sepuluh) orang bulan (OB) dengan besaran honorarium Rp20.000.000 per orang bulan. Konsultan bertugas memberikan dukungan teknis dalam perencanaan dan pelaksanaan kegiatan budidaya pertanian guna meningkatkan produktivitas, kualitas hasil, dan keberlanjutan usaha tani dalam lingkup program. Ruang lingkup pekerjaan meliputi analisis kondisi agroekosistem, penyusunan rekomendasi teknis budidaya (pola tanam, pemupukan, pengendalian hama dan penyakit, serta praktik pertanian berkelanjutan), pendampingan teknis di lapangan, serta evaluasi penerapan teknologi budidaya. Konsultan juga bertanggung jawab menyusun laporan berkala dan laporan akhir yang memuat hasil analisis, capaian, serta rekomendasi perbaikan. Pelaksanaan tugas harus berbasis data dan kondisi lokal, menghasilkan rekomendasi yang aplikatif, serta selaras dengan pedoman teknis dan tujuan program yang berlaku', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527749);
