INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094020', 66094020, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND (2 kali x 35 orang)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 42000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 70, OH, @ 600000 )', '1. Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND (2 kali x 35 orang) ( 70, OH, @ 600000 );', 'Pertemuan koordinasi, pembinaan, monitoring, evaluasi, dan sinkronisasi UPLAND merupakan kegiatan pertemuan yang dilaksanakan untuk memperkuat koordinasi antar pihak terkait dalam pelaksanaan program UPLAND. Kegiatan ini bertujuan untuk melakukan pembinaan terhadap pelaksana kegiatan, memantau perkembangan pelaksanaan program, mengevaluasi capaian kegiatan, serta menyelaraskan rencana kerja agar pelaksanaan program dapat berjalan secara efektif dan sesuai dengan target yang telah ditetapkan. Pelaksanaan kegiatan ini dilaksanakan sebanyak dua kali dengan melibatkan peserta yang berasal dari unsur pengelola program, pelaksana kegiatan, serta pihak terkait lainnya. Kegiatan pertemuan dilaksanakan di tempat yang memadai dan dilengkapi dengan fasilitas pendukung seperti ruang rapat, meja dan kursi, perangkat presentasi (LCD projector dan layar), sound system, serta sarana pendukung lainnya yang diperlukan untuk kelancaran kegiatan. Selain itu, kegiatan ini juga mencakup penyediaan konsumsi bagi peserta selama pelaksanaan kegiatan sesuai dengan standar layanan pertemuan. Dengan terselenggaranya kegiatan ini, diharapkan tercapai keselarasan dalam pelaksanaan program, peningkatan kualitas pengelolaan kegiatan, serta tersusunnya rekomendasi dan tindak lanjut yang mendukung keberhasilan program UPLAND.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527764);
