INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093999', 66093999, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Fullboard dalam rangka Monitoring dan Evaluasi', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 50, OH, @ 600000 )', '1. Paket Meeting Fullboard dalam rangka Monitoring dan Evaluasi ( 50, OH, @ 600000 );', 'Paket meeting fullboard dalam rangka kegiatan Monitoring dan Evaluasi disediakan untuk mendukung pelaksanaan rapat koordinasi, pemantauan, serta evaluasi pelaksanaan program/kegiatan yang melibatkan peserta sebanyak 50 Orang Hari (OH) dengan standar biaya Rp600.000 per orang per hari. Paket ini dirancang untuk memberikan fasilitas pertemuan yang memadai sehingga proses pemaparan, diskusi, serta penilaian capaian kegiatan dapat berlangsung secara efektif dan terkoordinasi. Fasilitas yang disediakan dalam paket ini meliputi ruang pertemuan yang representatif, nyaman, dan berpendingin udara (AC) dengan kapasitas yang mampu menampung seluruh peserta kegiatan. Tata letak ruangan dapat disesuaikan dengan kebutuhan kegiatan, seperti classroom, U-shape, atau theatre style, guna mendukung interaksi, presentasi materi, serta diskusi antar peserta. Ruangan juga dilengkapi dengan LCD proyektor, layar proyeksi, sound system yang memadai, microphone (wired atau wireless), serta flipchart atau whiteboard lengkap dengan spidol dan perlengkapan tulis lainnya untuk menunjang kegiatan presentasi dan pencatatan hasil diskusi. Dalam paket fullboard ini juga termasuk penyediaan konsumsi selama kegiatan berlangsung, yang terdiri dari 1 (satu) kali makan siang dan 1 (satu) kali makan malam, serta 2 (dua) kali coffee break pada pagi dan sore hari yang dilengkapi dengan makanan ringan (snack) dan minuman seperti kopi dan teh. Seluruh konsumsi disiapkan dengan memperhatikan standar kebersihan, kualitas, dan kecukupan bagi seluruh peserta. Selain itu, paket juga mencakup penyediaan perlengkapan rapat dasar seperti air mineral untuk peserta, notepad, dan alat tulis, serta dukungan layanan dari pihak penyedia tempat berupa tenaga teknis untuk membantu pengoperasian peralatan pertemuan agar kegiatan dapat berlangsung dengan lancar. Dengan tersedianya paket meeting fullboard sebesar Rp600.000 per orang per hari untuk 50 OH, diharapkan kegiatan Monitoring dan Evaluasi dapat terlaksana secara optimal, mendukung proses penyampaian laporan perkembangan kegiatan, identifikasi kendala, serta perumusan langkah perbaikan dan tindak lanjut program secara komprehensif.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527897);
