INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094027', 66094027, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 42000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 70, OH, @ 600000 )', '1. Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND ( 70, OH, @ 600000 );', 'Pertemuan koordinasi, pembinaan, monitoring, evaluasi, dan sinkronisasi UPLAND merupakan kegiatan pertemuan yang dilaksanakan untuk memperkuat koordinasi serta meningkatkan efektivitas pelaksanaan program UPLAND. Kegiatan ini bertujuan untuk melakukan pembinaan kepada pelaksana kegiatan, memantau perkembangan pelaksanaan program, mengevaluasi capaian kegiatan, serta menyelaraskan rencana kerja antar pihak terkait agar pelaksanaan program dapat berjalan secara optimal. Kegiatan pertemuan ini melibatkan unsur pengelola program, pelaksana kegiatan, serta pemangku kepentingan terkait lainnya. Pelaksanaan kegiatan dilaksanakan di tempat yang memadai dan dilengkapi dengan fasilitas pendukung seperti ruang pertemuan, meja dan kursi, pendingin ruangan, perangkat presentasi (LCD projector dan layar), sound system, serta fasilitas pendukung lainnya yang diperlukan untuk menunjang kelancaran kegiatan. Selain itu, kegiatan ini juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung sesuai dengan standar layanan pertemuan. Melalui kegiatan ini diharapkan tercipta keselarasan dalam pelaksanaan program, peningkatan kualitas pengelolaan kegiatan, serta tersusunnya rekomendasi dan tindak lanjut yang mendukung pencapaian tujuan program UPLAND.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527915);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66092043', 66092043, 'analyze_legacy', 'Kementerian Kebudayaan', 'central', 'Direktorat Bina Sumber Daya Manusia Lembaga dan Pranata Kebudayaan', 'Pemeliharaan Printer', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 5000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 5, unit, @ 1000000 )', '1. Pemeliharaan Printer ( 5, unit, @ 1000000 );', '1. Pemeliharaan Printer', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527916);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66050769', 66050769, 'analyze_legacy', 'Kab. Banyuwangi', 'kabkota', 'UPT Puskesmas Wonosobo', 'Belanja Makanan dan Minuman Rapat sub keg. OPP Puskesmas Wonosobo', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Banyuwangi (Kab.)', 18662500, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Makanan dan Minuman Rapat sub keg. OPP Puskesmas Wonosobo Sumber Dana : DAU', 'Nasi Kotak Snack', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527917);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093957', 66093957, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsultan DSC', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 1100000000, 'March 2021', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 1, Pkt, @ 1100000000 )', '1. Konsultan DSC ( 1, Pkt, @ 1100000000 );', 'Latar Belakang Program UPLAND Project merupakan program pengembangan pertanian lahan kering dan dataran tinggi yang dilaksanakan oleh Kementerian Pertanian Republik Indonesia dengan dukungan pendanaan dari Islamic Development Bank dan International Fund for Agricultural Development. Salah satu komponen utama program adalah pembangunan dan rehabilitasi infrastruktur pendukung pertanian seperti jalan usaha tani, irigasi, embung, dan sarana produksi. Untuk menjamin bahwa kegiatan infrastruktur dilaksanakan sesuai standar teknis, mutu, waktu, dan biaya, diperlukan Design and Supervision Consultant (DSC) sebagai konsultan yang mendukung perencanaan teknis dan pengawasan pelaksanaan konstruksi. Maksud dan Tujuan Penugasan DSC bertujuan untuk memberikan dukungan teknis dalam: penyusunan desain teknis kegiatan infrastruktur; verifikasi kelayakan teknis lokasi kegiatan; pengawasan mutu pelaksanaan konstruksi; pengendalian kesesuaian volume pekerjaan dengan kontrak; pengawasan progres pelaksanaan fisik. Ruang Lingkup Pekerjaan DSC melaksanakan pekerjaan yang meliputi: a. Perencanaan Teknis melakukan survei lapangan; menyusun desain teknis rinci (DED); menyusun gambar kerja dan spesifikasi teknis; menyusun engineer estimate / RAB; melakukan verifikasi kelayakan teknis lokasi. b. Pengawasan Pelaksanaan Konstruksi mengawasi pelaksanaan pekerjaan fisik di lapangan; memastikan kesesuaian pekerjaan dengan gambar dan spesifikasi; memeriksa kualitas material dan metode kerja; memantau progres fisik harian, mingguan, dan bulanan. c. Pengendalian Kontrak memeriksa volume pekerjaan; memberikan rekomendasi atas perubahan pekerjaan bila diperlukan; memverifikasi pembayaran progres pekerjaan. d. Pelaporan menyusun laporan kemajuan pekerjaan; menyusun laporan pengawasan berkala; menyampaikan rekomendasi teknis kepada PMU/PIU. Output yang Diharapkan Output DSC meliputi: dokumen desain teknis; gambar kerja; RAB teknis; laporan pengawasan berkala; laporan evaluasi mutu pekerjaan; laporan akhir pengawasan. Pendekatan Pelaksanaan Pelaksanaan dilakukan melalui: survei lapangan; koordinasi teknis dengan pelaksana kegiatan; inspeksi rutin; review dokumen kontrak; evaluasi hasil pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527918);
