INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094011', 66094011, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsumsi Rapat dalam Kantor', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 13000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 260, OK, @ 50000 )', '1. Konsumsi Rapat dalam Kantor ( 260, OK, @ 50000 );', 'Konsumsi rapat dalam kantor merupakan penyediaan makanan dan minuman yang diperuntukkan bagi peserta rapat yang dilaksanakan di lingkungan kantor guna mendukung kelancaran kegiatan koordinasi, pembahasan teknis, serta evaluasi pelaksanaan program. Kegiatan ini dialokasikan sebanyak 260 Orang Konsumsi (OK) dengan satuan biaya sebesar Rp50.000 per orang. Penyediaan konsumsi rapat bertujuan untuk menunjang berbagai kegiatan rapat internal, seperti rapat koordinasi, rapat teknis, pembahasan program, rapat evaluasi kegiatan, serta pertemuan kerja lainnya yang berkaitan dengan pelaksanaan tugas dan kegiatan program. Konsumsi yang disediakan umumnya berupa makanan ringan/snack dan minuman, yang disiapkan sesuai dengan standar konsumsi rapat dalam kantor serta memperhatikan aspek kebersihan, kualitas, dan kelayakan konsumsi. Konsumsi rapat diberikan kepada peserta rapat sesuai dengan jumlah kehadiran dalam setiap kegiatan pertemuan. Penyediaannya dilakukan selama kegiatan berlangsung guna menciptakan suasana rapat yang lebih nyaman dan kondusif, sehingga peserta dapat mengikuti diskusi dan proses pengambilan keputusan dengan lebih optimal. Dengan adanya dukungan konsumsi rapat dalam kantor ini, diharapkan pelaksanaan kegiatan rapat dan koordinasi internal dapat berjalan secara lebih efektif, tertib, dan produktif, sehingga mendukung kelancaran pelaksanaan kegiatan serta pencapaian target program yang telah ditetapkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527960);
