INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66055506', 66055506, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Komputer Suplies Layanan Peliputan dan Dokumentasi Program Kemnaker', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 12600000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '12 Kegiatan', 'Pekerjaan ini meliputi pengadaan dan penyediaan komputer suplies/perlengkapan penunjang operasional kantor untuk Layanan Peliputan dan Dokumentasi Program Kemnaker, guna memastikan kelancaran proses pengambilan, pengolahan, penyimpanan, dan distribusi materi publikasi (foto, video, dan naskah), termasuk pemenuhan kebutuhan bahan habis pakai dan aksesoris/peripheral terkait komputer dan perangkat dokumentasi, serta kegiatan pengemasan, pengiriman ke lokasi/ruang kerja yang ditetapkan, pemeriksaan kesesuaian jumlah dan kondisi barang, dan serah terima barang disertai bukti/berita acara sesuai ketentuan yang berlaku.', 'Spesifikasi pengadaan mencakup komputer suplies/perlengkapan penunjang yang seluruhnya dalam kondisi baru, layak pakai, dan sesuai fungsi untuk kebutuhan peliputan-dokumentasi, seperti bahan habis pakai (mis. tinta/toner/consumable sejenis sesuai perangkat yang digunakan) serta perlengkapan/peripheral dan media penyimpanan (misalnya kabel/konektor/adaptor, mouse/keyboard/headset, card reader, flashdisk/SSD/HDD eksternal/SD card) dengan ketentuan kompatibel dengan perangkat eksisting, berstandar mutu pabrikan, tidak cacat, memiliki masa berlaku/ketahanan yang memadai (khusus consumable tidak kedaluwarsa), disertai garansi/resmi pabrikan untuk item elektronik sesuai ketentuan, serta pengiriman aman (packing memadai) dan kelengkapan dokumen (faktur/nota, daftar barang, dan berita acara serah terima).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2527999);
