INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094000', 66094000, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Perbanyakan Laporan Akhir Tahun', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 4000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 40, PKT, @ 100000 )', '1. Perbanyakan Laporan Akhir Tahun ( 40, PKT, @ 100000 );', 'Perbanyakan Laporan Akhir Tahun dilaksanakan untuk mendukung kegiatan dokumentasi, pelaporan, serta penyebarluasan informasi terkait pelaksanaan program/kegiatan selama satu tahun anggaran. Kegiatan ini mencakup proses pencetakan dan penggandaan dokumen laporan sebanyak 40 paket (PKT) dengan standar biaya sebesar Rp100.000 per paket. Setiap paket laporan akhir tahun dicetak menggunakan kertas HVS ukuran A4 dengan kualitas minimal 70–80 gram, dengan hasil cetakan yang jelas, rapi, dan mudah dibaca. Proses pencetakan dapat menggunakan tinta hitam putih maupun berwarna pada bagian tertentu yang memerlukan penegasan seperti grafik, tabel, foto kegiatan, atau bagian penting lainnya dalam laporan. Dokumen disusun sesuai dengan sistematika laporan yang telah ditetapkan, meliputi halaman sampul, kata pengantar, daftar isi, isi laporan, lampiran, serta dokumentasi pendukung apabila tersedia. Untuk menjaga kerapihan dan ketahanan dokumen, setiap laporan dilengkapi dengan sampul (cover) yang dicetak pada kertas yang lebih tebal atau menggunakan cover khusus, serta dilakukan proses penjilidan (binding) seperti soft cover dengan lem panas, spiral, atau jenis jilid lain yang rapi dan kuat sehingga dokumen mudah digunakan dan disimpan sebagai arsip. Selain itu, penyedia jasa juga memastikan proses penyusunan halaman, pengecekan hasil cetak, serta pemotongan dan finishing dokumen dilakukan dengan baik agar setiap paket laporan memiliki kualitas yang seragam dan sesuai standar dokumen resmi. Hasil perbanyakan laporan kemudian diserahkan dalam kondisi rapi dan siap digunakan untuk keperluan distribusi, dokumentasi, maupun arsip instansi. Dengan dilaksanakannya kegiatan perbanyakan Laporan Akhir Tahun sebanyak 40 paket, diharapkan dokumen laporan dapat tersedia secara memadai sebagai bahan pertanggungjawaban kegiatan, referensi evaluasi program, serta sumber informasi bagi pihak terkait dalam mendukung perencanaan dan pelaksanaan kegiatan di periode berikutnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528078);
