INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093969', 66093969, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Driver', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 96000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 24, OB, @ 4000000 )', '1. Driver ( 24, OB, @ 4000000 );', 'Pengadaan tenaga Driver dilaksanakan selama 24 (dua puluh empat) orang bulan (OB) dengan besaran honorarium Rp4.000.000 per orang bulan. Driver bertugas mendukung operasional kendaraan dinas dalam rangka pelaksanaan kegiatan program, baik untuk kegiatan perkantoran maupun kegiatan lapangan. Ruang lingkup pekerjaan meliputi pengemudian kendaraan secara aman dan bertanggung jawab, memastikan kendaraan dalam kondisi siap pakai, melakukan pengecekan rutin (BBM, oli, tekanan ban, dan kondisi umum kendaraan), serta menjaga kebersihan dan kelayakan kendaraan. Driver juga bertanggung jawab mematuhi peraturan lalu lintas serta menjaga keselamatan penumpang selama perjalanan. Pelaksanaan tugas harus menjamin ketepatan waktu, kedisiplinan, serta menjaga kerahasiaan dan etika dalam mendukung kegiatan operasional program sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528162);
