INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093960', 66093960, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Economic Financial Analysis (EFA)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 120000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 10, OB, @ 12000000 )', '1. Economic Financial Analysis (EFA) ( 10, OB, @ 12000000 );', 'Pengadaan tenaga ahli untuk pelaksanaan Economic Financial Analysis (EFA) dilaksanakan selama 10 (sepuluh) orang bulan (OB) dengan besaran honorarium Rp12.000.000 per orang bulan. Kegiatan ini bertujuan untuk melakukan analisis kelayakan ekonomi dan finansial terhadap komponen kegiatan program guna memastikan efektivitas, efisiensi, dan keberlanjutan investasi. Ruang lingkup pekerjaan meliputi pengumpulan dan pengolahan data teknis serta finansial, penyusunan proyeksi biaya dan manfaat (cost-benefit analysis), analisis indikator kelayakan seperti NPV, IRR, B/C ratio, dan Payback Period, serta analisis sensitivitas terhadap berbagai skenario. Selain itu, tenaga ahli bertugas menyusun laporan analisis lengkap beserta rekomendasi sebagai dasar pengambilan keputusan manajemen program. Pelaksanaan pekerjaan harus menghasilkan dokumen analisis yang komprehensif, berbasis data yang valid, serta sesuai dengan pedoman teknis dan standar analisis ekonomi yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528214);
