INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094006', 66094006, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Inspektor Lapangan', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 1568000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 224, OB, @ 7000000 )', '1. Inspektor Lapangan ( 224, OB, @ 7000000 );', 'Inspektor Lapangan merupakan tenaga profesional yang ditugaskan untuk melaksanakan kegiatan pengawasan teknis dan pemantauan pelaksanaan kegiatan di lapangan guna memastikan bahwa seluruh pekerjaan dilaksanakan sesuai dengan rencana kerja, ketentuan teknis, serta standar mutu yang telah ditetapkan dalam program. Penugasan Inspektor Lapangan dilaksanakan selama 224 Orang Bulan (OB) dengan nilai jasa sebesar Rp7.000.000 per orang per bulan. Tugas utama Inspektor Lapangan meliputi kegiatan pemantauan, pemeriksaan, dan evaluasi terhadap pelaksanaan kegiatan di lokasi proyek atau kegiatan program. Dalam menjalankan tugasnya, Inspektor Lapangan memastikan bahwa kegiatan yang dilaksanakan oleh pelaksana kegiatan atau pihak terkait telah sesuai dengan spesifikasi teknis, jadwal pelaksanaan, serta ketentuan administrasi yang berlaku. Inspektor Lapangan juga bertanggung jawab untuk melakukan pengumpulan data dan informasi di lapangan, termasuk mendokumentasikan perkembangan kegiatan, mengidentifikasi kendala atau permasalahan yang muncul selama pelaksanaan kegiatan, serta memberikan rekomendasi teknis yang diperlukan guna mendukung kelancaran pelaksanaan program. Selain itu, Inspektor Lapangan melakukan koordinasi dengan tim pelaksana program, pemerintah daerah, kelompok masyarakat, serta pihak terkait lainnya dalam rangka memastikan keterpaduan pelaksanaan kegiatan di lapangan. Hasil pemantauan dan pengawasan kemudian disusun dalam bentuk laporan kegiatan secara berkala, yang memuat perkembangan pelaksanaan pekerjaan, tingkat capaian kegiatan, serta rekomendasi perbaikan apabila diperlukan. Dengan adanya dukungan Inspektor Lapangan, diharapkan pelaksanaan kegiatan di lapangan dapat berjalan secara tertib, transparan, dan sesuai dengan standar teknis yang telah ditetapkan, sehingga tujuan program dapat tercapai secara efektif dan memberikan manfaat yang optimal bagi masyarakat sasaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528252);
