INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094014', 66094014, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 50, OH, @ 600000 )', '1. Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND ( 50, OH, @ 600000 );', 'Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND merupakan layanan penyelenggaraan pertemuan yang disediakan oleh hotel atau tempat pertemuan yang memiliki fasilitas memadai untuk mendukung pelaksanaan kegiatan secara efektif dan kondusif. Kegiatan ini dialokasikan sebanyak 50 Orang Hari (OH) dengan satuan biaya sebesar Rp600.000 per orang per hari. Paket meeting fullboard mencakup penyediaan ruang pertemuan yang representatif dan nyaman, dengan kapasitas yang memadai untuk menampung seluruh peserta kegiatan. Ruang pertemuan dilengkapi dengan fasilitas penunjang kegiatan rapat dan diskusi, antara lain meja dan kursi sesuai kebutuhan tata ruang (classroom, U-shape, atau theater), LCD proyektor, layar proyektor, sound system, microphone, papan tulis atau flipchart, serta akses listrik dan jaringan internet guna mendukung kelancaran presentasi, diskusi kelompok, dan penyampaian materi selama kegiatan berlangsung. Selain fasilitas ruang pertemuan, paket fullboard juga mencakup konsumsi bagi peserta selama kegiatan berlangsung, yang terdiri dari tiga kali makan utama (sarapan, makan siang, dan makan malam) serta dua kali coffee break setiap hari pelaksanaan kegiatan. Konsumsi disediakan oleh pihak penyedia jasa dengan memperhatikan standar kebersihan, kualitas makanan, serta kecukupan gizi bagi seluruh peserta kegiatan. Paket ini juga mencakup fasilitas akomodasi atau penginapan bagi peserta, berupa kamar hotel yang layak dan nyaman sesuai dengan standar tempat kegiatan. Fasilitas kamar umumnya meliputi tempat tidur, kamar mandi dalam, perlengkapan mandi, pendingin ruangan, serta fasilitas pendukung lainnya yang diperlukan oleh peserta selama kegiatan berlangsung. Selain itu, penyedia layanan juga memberikan dukungan layanan teknis dan operasional, seperti penataan ruang rapat, kesiapan peralatan presentasi, kebersihan ruangan, serta pelayanan konsumsi kepada peserta. Dukungan ini bertujuan untuk memastikan bahwa seluruh rangkaian kegiatan dapat berjalan dengan tertib, lancar, dan sesuai dengan agenda yang telah ditetapkan. Dengan adanya paket meeting fullboard ini, diharapkan kegiatan penyiapan exit strategi dan keberlanjutan Program UPLAND dapat terlaksana secara optimal melalui proses diskusi, koordinasi, dan perumusan strategi yang komprehensif, sehingga menghasilkan rekomendasi yang dapat mendukung keberlanjutan program dan memberikan manfaat jangka panjang bagi masyarakat di wilayah sasaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528330);
