INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094015', 66094015, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'ATK', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 6000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 12, BLN, @ 500000 )', '1. ATK ( 12, BLN, @ 500000 );', 'Penyediaan Alat Tulis Kantor (ATK) merupakan bagian dari dukungan operasional administrasi yang diperlukan untuk menunjang kelancaran pelaksanaan kegiatan program. Kegiatan ini dialokasikan selama 12 bulan dengan satuan biaya sebesar Rp500.000 per bulan, yang digunakan untuk memenuhi kebutuhan perlengkapan administrasi dan kegiatan perkantoran selama pelaksanaan program berlangsung. ATK yang disediakan meliputi berbagai perlengkapan yang digunakan dalam kegiatan administrasi dan dokumentasi, antara lain kertas HVS berbagai ukuran, pulpen, pensil, spidol, stabilo, buku catatan, map folder, ordner, sticky notes, amplop, paper clip, binder clip, serta perlengkapan pendukung lainnya yang diperlukan dalam kegiatan perkantoran. Perlengkapan ATK ini digunakan untuk mendukung berbagai aktivitas kerja seperti penyusunan laporan kegiatan, pencatatan hasil rapat, pengarsipan dokumen, penyusunan bahan presentasi, serta kegiatan administrasi lainnya yang berkaitan dengan pelaksanaan program. Penggunaan ATK dilakukan secara efektif dan efisien sesuai dengan kebutuhan operasional tim pelaksana kegiatan. Pengadaan ATK dilakukan secara berkala atau sesuai kebutuhan selama periode kegiatan berlangsung, sehingga ketersediaan perlengkapan administrasi tetap terjaga dan dapat dimanfaatkan secara optimal oleh tim pelaksana. Dengan adanya dukungan ATK yang memadai, diharapkan seluruh proses administrasi, dokumentasi, dan pengelolaan kegiatan program dapat berjalan dengan tertib, efektif, dan akuntabel.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528336);
