INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093995', 66093995, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Project Implementation advisor', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 240000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 12, OB, @ 20000000 )', '1. Project Implementation advisor ( 12, OB, @ 20000000 );', 'Pengadaan Project Implementation Advisor dilaksanakan selama 12 (dua belas) orang bulan (OB) dengan besaran honorarium Rp20.000.000 per orang bulan. Advisor bertugas memberikan arahan dan dukungan strategis dalam pelaksanaan program agar kegiatan dapat berjalan efektif, efisien, serta sesuai dengan rencana kerja, target capaian, dan ketentuan yang berlaku. Ruang lingkup pekerjaan meliputi pemberian masukan strategis terkait perencanaan dan implementasi kegiatan, identifikasi potensi kendala serta rekomendasi solusi, penguatan koordinasi antar pemangku kepentingan, serta pendampingan dalam proses monitoring dan evaluasi program. Advisor juga berperan dalam memberikan rekomendasi kebijakan dan perbaikan pelaksanaan program berdasarkan hasil analisis dan evaluasi. Pelaksanaan tugas harus menghasilkan rekomendasi yang konstruktif dan aplikatif guna meningkatkan kualitas implementasi program serta memastikan pencapaian tujuan kegiatan secara optimal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528369);
