INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094123', 66094123, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket meeting dalam rangka Rapat, Workshop, FGD Exit Strategi Keg Upland', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 329600000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 412, OH, @ 800000 )', '1. Paket meeting dalam rangka Rapat, Workshop, FGD Exit Strategi Keg Upland ( 412, OH, @ 800000 );', 'Paket meeting dalam rangka rapat, workshop, dan Focus Group Discussion (FGD) exit strategi kegiatan UPLAND dilaksanakan sebagai bagian dari upaya merumuskan strategi keberlanjutan program setelah berakhirnya masa pelaksanaan kegiatan. Kegiatan ini bertujuan untuk menyusun langkah-langkah strategis yang dapat memastikan bahwa hasil, manfaat, serta berbagai capaian program UPLAND tetap dapat dipertahankan dan dikembangkan oleh para pemangku kepentingan di tingkat daerah maupun masyarakat. Kegiatan ini dilaksanakan dengan total 412 Orang Hari (OH) yang melibatkan berbagai pihak terkait, antara lain pengelola program, perwakilan pemerintah daerah, penyuluh pertanian, fasilitator lapangan, kelompok tani, serta pemangku kepentingan lainnya yang berperan dalam pelaksanaan dan pengembangan program UPLAND. Melalui kegiatan rapat, workshop, dan FGD ini, para peserta akan melakukan pembahasan secara mendalam mengenai capaian program, tantangan yang dihadapi selama pelaksanaan kegiatan, serta peluang dan strategi untuk menjaga keberlanjutan hasil-hasil program. Dalam kegiatan ini juga akan dilakukan identifikasi terhadap potensi kelembagaan, dukungan sumber daya, serta sinergi antar pemangku kepentingan yang dapat mendukung keberlanjutan program di masa mendatang. Selain itu, peserta akan merumuskan berbagai rekomendasi dan rencana tindak lanjut yang dapat dijadikan sebagai dasar dalam pelaksanaan strategi keberlanjutan program di tingkat daerah maupun masyarakat. Pelaksanaan kegiatan difasilitasi melalui paket meeting yang menyediakan sarana dan prasarana pertemuan yang memadai. Fasilitas yang disediakan meliputi ruang pertemuan yang representatif, peralatan presentasi seperti LCD proyektor, layar, sound system, meja dan kursi pertemuan, serta perlengkapan penunjang lainnya yang diperlukan selama kegiatan berlangsung. Selain penyediaan fasilitas ruang pertemuan dan perlengkapan kegiatan, paket meeting juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung, seperti makan dan coffee break sesuai dengan standar pelaksanaan kegiatan rapat atau pertemuan. Penyediaan fasilitas ini bertujuan untuk menunjang kenyamanan peserta sehingga proses diskusi, koordinasi, dan perumusan strategi dapat berjalan secara efektif dan produktif. Melalui kegiatan ini diharapkan dapat dihasilkan rumusan exit strategi kegiatan UPLAND yang komprehensif, terarah, dan dapat diimplementasikan secara berkelanjutan oleh para pemangku kepentingan. Dengan demikian, manfaat program yang telah dilaksanakan dapat terus berlanjut serta memberikan kontribusi terhadap peningkatan kesejahteraan masyarakat dan pengembangan sektor pertanian secara berkelanjutan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528409);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093950', 66093950, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'ATK', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 13022000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 1, Thn, @ 13022000 )', 'ATK yang disediakan meliputi berbagai kebutuhan alat tulis dan perlengkapan kantor seperti kertas, pulpen, pensil, spidol, buku catatan, map, ordner, stapler, isi stapler, sticky notes, serta perlengkapan pendukung administrasi lainnya yang diperlukan dalam kegiatan perkantoran.', 'ATK merupakan penyediaan alat tulis kantor yang digunakan untuk mendukung kelancaran kegiatan administrasi dan operasional perkantoran selama satu tahun anggaran. Pengadaan ATK ini bertujuan untuk memastikan tersedianya perlengkapan kerja yang dibutuhkan dalam pelaksanaan tugas-tugas administrasi, pengolahan dokumen, pencatatan data, serta kegiatan perkantoran lainnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528410);
