INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094122', 66094122, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Belanja Bahan', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 9869000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '2 Paket', '1. ATK, Perbanyakan, Pengiriman dan Fotocopy ( 1, Pkt, @ 4369000 ); 2. Spanduk/Banner/Photoboot ( 11, Pkt, @ 500000 );', '1. ATK, Perbanyakan, Pengiriman dan Fotocopy (1 Paket @ Rp4.369.000) Pengadaan ATK, perbanyakan, pengiriman, dan fotocopy dilaksanakan dalam 1 (satu) paket pekerjaan dengan nilai sebesar Rp4.369.000 untuk mendukung kelancaran administrasi dan pelaksanaan kegiatan. Ruang lingkup meliputi penyediaan alat tulis kantor, pencetakan dan penggandaan dokumen/materi kegiatan, fotokopi, penjilidan sederhana, serta pengiriman dokumen melalui jasa kurir atau ekspedisi sesuai kebutuhan. Seluruh barang dan jasa yang disediakan harus berkualitas baik, jumlah sesuai kebutuhan kegiatan, serta didukung bukti transaksi yang sah. Pelaksanaan pengadaan dilakukan secara efisien, efektif, dan sesuai ketentuan administrasi yang berlaku. 2. Spanduk/Banner/Photobooth (11 Paket @ Rp500.000) Pengadaan spanduk, banner, dan/atau photobooth dilaksanakan sebanyak 11 (sebelas) paket dengan satuan biaya Rp500.000 per paket untuk mendukung identitas dan publikasi kegiatan. Ruang lingkup meliputi desain grafis, pencetakan dengan bahan berkualitas (flexi atau bahan setara), ukuran menyesuaikan kebutuhan lokasi kegiatan, serta pemasangan di tempat acara. Desain harus mencantumkan judul kegiatan, waktu, lokasi, serta identitas program dan logo terkait sesuai pedoman yang berlaku. Hasil cetak harus memiliki kualitas warna yang baik, tidak mudah pudar, serta terpasang rapi sehingga mendukung dokumentasi dan citra profesional kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528518);
