INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094035', 66094035, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Spanduk/Banner/Photobooth', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 3000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 6, Pkt, @ 500000 )', '1. Spanduk/Banner/Photobooth ( 6, Pkt, @ 500000 );', 'Penyediaan spanduk, banner, dan photobooth merupakan bagian dari kebutuhan publikasi dan dokumentasi kegiatan yang bertujuan untuk mendukung penyelenggaraan kegiatan agar lebih informatif, tertata, dan mudah dikenali oleh peserta maupun pihak terkait. Kegiatan ini dialokasikan sebanyak 6 paket (Pkt) dengan satuan biaya sebesar Rp500.000 per paket. Spanduk atau banner digunakan sebagai media informasi dan identitas kegiatan, yang memuat judul kegiatan, waktu pelaksanaan, lokasi kegiatan, serta identitas program atau instansi penyelenggara. Spanduk atau banner dipasang pada lokasi kegiatan yang strategis agar mudah terlihat oleh peserta kegiatan maupun tamu undangan. Selain itu, penyediaan photobooth juga bertujuan untuk mendukung kegiatan dokumentasi selama pelaksanaan acara. Photobooth biasanya dilengkapi dengan desain latar belakang (backdrop) yang memuat tema kegiatan, logo instansi atau program, serta elemen visual lain yang mendukung identitas kegiatan. Photobooth dapat dimanfaatkan oleh peserta kegiatan sebagai sarana dokumentasi dan publikasi kegiatan. Proses penyediaan spanduk, banner, dan photobooth meliputi perancangan desain, pencetakan, pemasangan, serta pembongkaran setelah kegiatan selesai. Bahan yang digunakan umumnya berupa flexi banner atau bahan sejenis yang memiliki kualitas cetak yang baik, tahan terhadap kondisi lingkungan, serta memiliki tampilan yang jelas dan mudah dibaca. Dengan adanya dukungan spanduk, banner, dan photobooth ini, diharapkan kegiatan dapat terselenggara dengan lebih informatif, tertib, dan terdokumentasi dengan baik, sekaligus mendukung penyebarluasan informasi mengenai kegiatan kepada peserta maupun pihak terkait.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528618);
