INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66055234', 66055234, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Seminar Kit Layanan Peliputan dan Dokumentasi Program Kemnaker', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pekerjaan penyediaan paket perlengkapan kegiatan (seminar/rapat koordinasi/bimtek/sosialisasi) untuk mendukung layanan kehumasan, peliputan, dan dokumentasi program Kemnaker, meliputi penyusunan/penyesuaian desain dan branding sesuai identitas kegiatan/Kemnaker, pengadaan dan produksi item seminar kit (misalnya tumbler, perlengkapan seminar kit lainnya, serta plakat penghargaan/apresiasi untuk narasumber/mitra/pihak terkait), quality control, pengemasan per paket, serta pengiriman, distribusi, dan serah-terima kepada PPK/Pejabat Penerima Hasil Pekerjaan pada lokasi dan jadwal yang ditetapkan; termasuk penyediaan contoh (dummy/sample) untuk persetujuan sebelum produksi massal dan penggantian item yang tidak sesuai spesifikasi, dengan jumlah paket/komposisi item disesuaikan kebutuhan kegiatan.', 'Seminar kit dapat terdiri dari goodie bag/tas seminar (bahan kain/kanvas/polyester setara, kuat, jahitan rapi), buku catatan (A5/A4 sesuai kebutuhan, kertas layak tulis, jilid rapi), pulpen (tinta jelas), atau tumbler (bahan food grade, tidak bocor, tutup rapat; kapasitas/model menyesuaikan kebutuhan), serta plakat (material akrilik/kayu/logam kombinasi setara, finishing rapi, tidak mudah pudar/terkelupas, memuat identitas kegiatan dan/atau logo Kemnaker melalui printing/laser engraving/UV print setara; dilengkapi dudukan dan kemasan/box pelindung; ukuran/ketebalan/jumlah mengikuti kebutuhan kegiatan); seluruh item wajib baru 100%, bebas cacat, hasil cetak/branding awet, warna dan tata letak mengikuti desain final yang disetujui PPK, dikemas rapi (per paket dan/atau per penerima), serta disertai daftar kuantitas dan berita acara serah terima.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528626);
