INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094010', 66094010, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Perbanyakan, Pengiriman dan Fotocopy', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 6000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 12, OB, @ 500000 )', '1. Perbanyakan, Pengiriman dan Fotocopy ( 12, OB, @ 500000 );', 'Kegiatan perbanyakan, pengiriman, dan fotocopy dokumen merupakan bagian dari dukungan operasional administrasi yang diperlukan untuk menunjang kelancaran pelaksanaan kegiatan program. Kegiatan ini dialokasikan selama 12 Orang Bulan (OB) dengan satuan biaya sebesar Rp500.000 per bulan, yang digunakan untuk mendukung proses penggandaan dokumen, distribusi dokumen, serta kebutuhan administrasi lainnya selama pelaksanaan kegiatan berlangsung. Perbanyakan dan fotocopy dokumen dilakukan untuk memenuhi kebutuhan penggandaan berbagai dokumen penting yang berkaitan dengan pelaksanaan kegiatan, seperti laporan kegiatan, dokumen administrasi, bahan rapat, materi pelatihan, surat menyurat, dokumen teknis, serta dokumen pendukung lainnya yang diperlukan oleh tim pelaksana maupun pemangku kepentingan terkait. Proses penggandaan dokumen dilakukan sesuai dengan kebutuhan kegiatan agar seluruh pihak yang terlibat dapat memperoleh dokumen secara lengkap dan tepat waktu. Selain itu, komponen kegiatan ini juga mencakup biaya pengiriman dokumen kepada pihak-pihak terkait, baik melalui jasa pengiriman maupun distribusi langsung. Pengiriman dokumen dilakukan untuk memastikan bahwa laporan, surat resmi, atau dokumen kegiatan lainnya dapat disampaikan kepada instansi terkait, mitra kerja, maupun pihak yang berkepentingan sesuai dengan ketentuan administrasi yang berlaku. Pelaksanaan kegiatan ini diharapkan dapat mendukung kelancaran administrasi, dokumentasi, serta koordinasi kegiatan program, sehingga seluruh proses pengelolaan dokumen dapat berjalan secara tertib, efektif, dan terdokumentasi dengan baik selama periode pelaksanaan kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528660);
