INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094017', 66094017, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Sewa Kendaraan', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 150000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 150, Hari, @ 1000000 )', '1. Sewa Kendaraan ( 150, Hari, @ 1000000 );', 'Sewa kendaraan merupakan penyediaan sarana transportasi yang digunakan untuk mendukung kelancaran pelaksanaan kegiatan operasional program, khususnya dalam menunjang mobilitas tim pelaksana dalam melaksanakan koordinasi, monitoring, evaluasi, serta kegiatan lapangan lainnya. Kegiatan ini dialokasikan selama 150 hari dengan satuan biaya sebesar Rp1.000.000 per hari. Kendaraan yang disewa merupakan kendaraan operasional yang layak pakai dan dalam kondisi baik, sehingga dapat digunakan secara aman dan nyaman untuk mendukung kegiatan perjalanan dinas maupun aktivitas lapangan. Kendaraan tersebut digunakan untuk keperluan seperti kunjungan lapangan, koordinasi dengan instansi terkait, monitoring dan evaluasi kegiatan, serta kegiatan operasional lainnya yang berkaitan dengan pelaksanaan program. Fasilitas sewa kendaraan umumnya mencakup kendaraan beserta pengemudi (driver) yang berpengalaman dan memahami kondisi wilayah operasional kegiatan. Selain itu, kendaraan yang digunakan harus memenuhi standar kelayakan operasional, memiliki dokumen kendaraan yang lengkap, serta dalam kondisi terawat guna memastikan keamanan dan keselamatan selama perjalanan. Penggunaan kendaraan dilakukan sesuai dengan kebutuhan kegiatan dan jadwal pelaksanaan program, baik untuk perjalanan dalam kota maupun luar kota yang berkaitan dengan pelaksanaan tugas program. Dengan adanya dukungan sewa kendaraan ini, diharapkan mobilitas tim pelaksana dapat berjalan dengan lebih efektif, efisien, dan tepat waktu, sehingga mendukung kelancaran pelaksanaan kegiatan serta pencapaian target program yang telah direncanakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528671);
