INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094051', 66094051, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting dalam rangka perencanaan  proyek', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 96000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 120, OH, @ 800000 )', '1. Paket Meeting dalam rangka perencanaan proyek ( 120, OH, @ 800000 );', 'Kegiatan paket meeting dalam rangka perencanaan proyek dilaksanakan sebagai bagian dari proses persiapan dan perumusan rencana kegiatan yang akan dilaksanakan dalam suatu program atau proyek. Pertemuan ini bertujuan untuk menyamakan pemahaman para pemangku kepentingan, menyusun rencana kerja yang terarah, serta memastikan bahwa seluruh tahapan kegiatan proyek dapat direncanakan secara sistematis, efektif, dan terukur. Kegiatan pertemuan ini dilaksanakan dengan total 120 Orang Hari (OH) yang melibatkan unsur pengelola program, tim perencana, tenaga teknis, serta pihak terkait lainnya yang memiliki peran dalam pelaksanaan proyek. Peserta kegiatan akan membahas berbagai aspek perencanaan proyek, termasuk penentuan target kegiatan, penyusunan jadwal pelaksanaan, identifikasi kebutuhan sumber daya, serta pembagian peran dan tanggung jawab masing-masing pihak. Pelaksanaan kegiatan difasilitasi dalam bentuk paket meeting yang menyediakan ruang pertemuan yang memadai dan kondusif untuk kegiatan diskusi dan koordinasi. Fasilitas yang disediakan meliputi ruang rapat, peralatan presentasi seperti LCD proyektor, layar, sound system, meja dan kursi pertemuan, serta perlengkapan rapat lainnya yang diperlukan untuk mendukung kelancaran kegiatan. Selain fasilitas pertemuan, paket meeting juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung sesuai dengan standar pelaksanaan kegiatan rapat atau pertemuan, seperti makan dan coffee break. Hal ini dimaksudkan untuk menunjang kenyamanan peserta sehingga kegiatan diskusi dan penyusunan rencana proyek dapat berjalan secara efektif. Dalam kegiatan ini akan dilakukan pembahasan mengenai konsep dan ruang lingkup proyek, penyusunan rencana kerja dan tahapan pelaksanaan kegiatan, identifikasi potensi risiko serta strategi mitigasinya, serta penyelarasan rencana kegiatan dengan kebijakan dan program yang telah ditetapkan. Hasil dari kegiatan ini diharapkan berupa dokumen atau kesepakatan rencana kerja proyek yang dapat dijadikan sebagai pedoman dalam pelaksanaan kegiatan selanjutnya. Dengan dilaksanakannya kegiatan paket meeting dalam rangka perencanaan proyek ini, diharapkan proses perencanaan dapat dilakukan secara komprehensif, terkoordinasi, dan menghasilkan rencana kerja yang jelas, terukur, serta dapat dilaksanakan secara efektif oleh seluruh pihak yang terlibat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528737);
