INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093961', 66093961, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsultan Individu Bidang Bussines Development', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 200000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 10, OB, @ 20000000 )', '1. Konsultan Individu Bidang Bussines Development ( 10, OB, @ 20000000 );', 'Pengadaan Konsultan Individu Bidang Business Development dilaksanakan selama 10 (sepuluh) orang bulan (OB) dengan besaran honorarium Rp20.000.000 per orang bulan. Konsultan bertugas memberikan dukungan strategis dalam pengembangan model bisnis, peningkatan nilai tambah produk, serta penguatan akses pasar dalam rangka mendukung keberlanjutan program. Ruang lingkup pekerjaan meliputi analisis potensi usaha dan rantai nilai (value chain), penyusunan strategi pengembangan usaha, identifikasi peluang kemitraan dan pembiayaan, pendampingan penyusunan rencana bisnis (business plan), serta fasilitasi akses pasar dan jejaring usaha. Konsultan juga bertanggung jawab menyusun laporan berkala dan laporan akhir yang memuat capaian, tantangan, serta rekomendasi pengembangan. Pelaksanaan tugas harus menghasilkan output yang terukur, aplikatif, dan selaras dengan tujuan program serta ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528809);
