INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094056', 66094056, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Pelatihan Manajemen Keuangan Korporasi', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 112000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 140, Pkt, @ 800000 )', '1. Paket Meeting Pelatihan Manajemen Keuangan Korporasi ( 140, Pkt, @ 800000 );', 'Paket meeting pelatihan manajemen keuangan korporasi dilaksanakan sebagai upaya untuk meningkatkan kapasitas dan pemahaman peserta dalam pengelolaan keuangan organisasi atau kelembagaan secara lebih profesional, transparan, dan akuntabel. Kegiatan ini bertujuan untuk memberikan pengetahuan dan keterampilan kepada peserta mengenai prinsip-prinsip dasar manajemen keuangan, perencanaan anggaran, pencatatan keuangan, serta pengelolaan dan pelaporan keuangan yang baik dalam suatu kelembagaan atau korporasi. Kegiatan pelatihan ini dilaksanakan dengan total 140 paket pertemuan yang melibatkan peserta dari unsur pengelola kelembagaan, kelompok usaha, pendamping program, serta pihak terkait lainnya yang memiliki peran dalam pengelolaan dan pengembangan kelembagaan ekonomi masyarakat. Melalui kegiatan ini, peserta akan memperoleh pemahaman mengenai konsep manajemen keuangan korporasi, penyusunan rencana anggaran, pengelolaan arus kas, pencatatan transaksi keuangan, serta penyusunan laporan keuangan yang dapat dipertanggungjawabkan. Pelaksanaan kegiatan difasilitasi melalui paket meeting pelatihan yang menyediakan sarana dan prasarana yang memadai untuk mendukung proses pembelajaran dan diskusi. Fasilitas yang disediakan meliputi ruang pelatihan yang representatif, peralatan presentasi seperti LCD proyektor, layar, sound system, meja dan kursi pelatihan, serta perlengkapan pendukung lainnya yang diperlukan selama kegiatan berlangsung. Selain penyediaan fasilitas ruang pelatihan dan perlengkapan kegiatan, paket meeting juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung, seperti makan dan coffee break sesuai dengan standar pelaksanaan kegiatan pelatihan atau pertemuan. Penyediaan fasilitas tersebut bertujuan untuk menunjang kenyamanan peserta sehingga kegiatan pelatihan dapat berjalan dengan efektif dan peserta dapat mengikuti seluruh rangkaian kegiatan dengan baik. Melalui kegiatan pelatihan manajemen keuangan korporasi ini diharapkan peserta memiliki kemampuan yang lebih baik dalam mengelola keuangan organisasi atau kelembagaan secara tertib, transparan, dan akuntabel. Dengan demikian, kegiatan ini diharapkan dapat mendukung penguatan kelembagaan ekonomi masyarakat serta meningkatkan keberlanjutan dan kinerja organisasi dalam menjalankan kegiatan usaha maupun program yang dilaksanakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528838);
