INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093963', 66093963, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsultan Spesialis Nutrisi  Gender', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 200000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 10, OB, @ 20000000 )', '1. Konsultan Spesialis Nutrisi Gender ( 10, OB, @ 20000000 );', 'Pengadaan Konsultan Spesialis Nutrisi dan Gender dilaksanakan selama 10 (sepuluh) orang bulan (OB) dengan besaran honorarium Rp20.000.000 per orang bulan. Konsultan bertugas memberikan dukungan teknis dalam integrasi aspek nutrisi dan kesetaraan gender ke dalam perencanaan, pelaksanaan, serta evaluasi kegiatan program. Ruang lingkup pekerjaan meliputi analisis situasi dan kebutuhan terkait nutrisi dan gender, penyusunan strategi intervensi yang responsif gender, penguatan kapasitas pemangku kepentingan, serta pendampingan implementasi kegiatan di lapangan. Konsultan juga bertanggung jawab melakukan monitoring dan evaluasi terhadap dampak program terhadap perbaikan gizi dan peningkatan peran serta akses perempuan, serta menyusun laporan berkala dan laporan akhir. Pelaksanaan tugas harus menghasilkan rekomendasi yang aplikatif, berbasis data, serta selaras dengan kebijakan dan pedoman teknis yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528882);
