INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094918', 66094918, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Belanja Sewa', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 56720000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1. Sewa Mobil ( 100, Hari, @ 567200 );', '1. Sewa Mobil ( 100, Hari, @ 567200 );', 'Kegiatan sewa mobil insidentil dilaksanakan untuk mendukung pelaksanaan monitoring kegiatan Operasi dan Pemeliharaan (OP) Jaringan Irigasi Tersier. Monitoring dilakukan guna memastikan kondisi fisik jaringan irigasi tetap berfungsi dengan baik, kegiatan pemeliharaan berjalan sesuai rencana, serta pelaksanaan anggaran dan administrasi dilaksanakan secara tertib dan akuntabel. Mengingat lokasi jaringan irigasi tersier tersebar di berbagai wilayah dan sebagian berada pada area persawahan atau lokasi dengan akses terbatas, diperlukan dukungan sarana transportasi yang fleksibel dan siap digunakan sesuai kebutuhan penugasan lapangan. Kendaraan sewa digunakan oleh tim teknis untuk melakukan peninjauan langsung kondisi saluran dan bangunan pelengkap, pengumpulan data dan dokumentasi, serta koordinasi dengan pengelola irigasi di tingkat lapangan. Kendaraan yang disediakan berupa kendaraan roda empat jenis MPV/minibus atau setara dalam kondisi laik jalan, terawat, dan dilengkapi dokumen kendaraan yang sah serta masih berlaku. Layanan sewa termasuk pengemudi yang memiliki SIM A aktif dan memahami wilayah penugasan untuk mendukung kelancaran mobilitas tim monitoring. Pelaksanaan sewa dilakukan secara harian sesuai kebutuhan kegiatan monitoring. Pembayaran dilaksanakan berdasarkan jumlah hari pemakaian riil yang dibuktikan dengan surat tugas dan berita acara penggunaan kendaraan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528940);
