INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093993', 66093993, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting dalam rangka Penyusunan Laporan Akhir', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 48000000, 'September 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 60, OH, @ 800000 )', '1. Paket Meeting dalam rangka Penyusunan Laporan Akhir ( 60, OH, @ 800000 );', 'Pengadaan paket meeting dalam rangka penyusunan laporan akhir dilaksanakan sebanyak 60 (enam puluh) orang hari (OH) dengan satuan biaya sebesar Rp800.000 per orang hari. Kegiatan ini bertujuan untuk memfasilitasi proses pembahasan, konsolidasi data, serta finalisasi dokumen laporan akhir kegiatan program secara komprehensif dan terkoordinasi. Paket meeting meliputi penyediaan ruang rapat yang representatif, konsumsi peserta berupa makan dan coffee break sesuai durasi kegiatan, serta fasilitas pendukung seperti LCD proyektor, layar, sound system, meja dan kursi rapat, alat tulis kantor, dan air mineral. Penyedia wajib memastikan ketersediaan fasilitas yang memadai, kualitas konsumsi yang baik dan higienis, serta dukungan teknis selama kegiatan berlangsung sehingga proses penyusunan laporan akhir dapat berjalan efektif dan tepat waktu. Seluruh pelaksanaan kegiatan harus didukung dengan dokumentasi dan bukti transaksi yang sah sesuai ketentuan administrasi yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528946);
