INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094055', 66094055, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Pelatihan Nutrisi bagi PPL dan Fasilitator Desa', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 176000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 220, OH, @ 800000 )', '1. Paket Meeting Pelatihan Nutrisi bagi PPL dan Fasilitator Desa ( 220, OH, @ 800000 );', 'Paket meeting pelatihan nutrisi bagi Penyuluh Pertanian Lapangan (PPL) dan fasilitator desa dilaksanakan sebagai bagian dari upaya peningkatan kapasitas sumber daya manusia dalam mendukung pelaksanaan program, khususnya yang berkaitan dengan pemahaman dan penerapan aspek gizi dan nutrisi di tingkat masyarakat. Kegiatan ini bertujuan untuk meningkatkan pengetahuan, pemahaman, serta keterampilan para peserta dalam mengintegrasikan aspek nutrisi dalam kegiatan pendampingan dan pemberdayaan masyarakat di wilayah kerja masing-masing. Kegiatan pelatihan ini dilaksanakan dengan total 220 Orang Hari (OH) yang melibatkan PPL, fasilitator desa, serta unsur terkait lainnya yang memiliki peran dalam mendukung kegiatan penyuluhan, pendampingan, dan penguatan kapasitas masyarakat. Melalui pelatihan ini, peserta akan memperoleh materi mengenai konsep dasar nutrisi, pentingnya pemenuhan gizi seimbang, serta strategi penerapan edukasi nutrisi kepada masyarakat, khususnya dalam mendukung peningkatan kualitas kesehatan dan kesejahteraan keluarga di wilayah pedesaan. Pelaksanaan kegiatan difasilitasi melalui paket meeting pelatihan yang menyediakan sarana dan prasarana yang memadai untuk mendukung proses pembelajaran. Fasilitas yang disediakan meliputi ruang pelatihan yang representatif, peralatan presentasi seperti LCD proyektor, layar, sound system, meja dan kursi pelatihan, serta perlengkapan pendukung lainnya yang diperlukan selama kegiatan berlangsung. Selain fasilitas ruang pelatihan dan perlengkapan kegiatan, paket meeting juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung, seperti makan dan coffee break sesuai dengan standar pelaksanaan kegiatan pelatihan. Penyediaan fasilitas ini bertujuan untuk mendukung kenyamanan peserta sehingga kegiatan pelatihan dapat berlangsung secara efektif dan peserta dapat mengikuti seluruh rangkaian materi dengan baik. Melalui kegiatan pelatihan ini diharapkan para PPL dan fasilitator desa memiliki pemahaman yang lebih baik mengenai aspek nutrisi serta mampu menyampaikan informasi dan edukasi kepada masyarakat secara tepat. Dengan demikian, kegiatan ini diharapkan dapat mendukung peningkatan kesadaran masyarakat terhadap pentingnya pemenuhan gizi seimbang serta berkontribusi terhadap peningkatan kualitas hidup masyarakat di wilayah pelaksanaan program.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2528989);
