INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094057', 66094057, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Literasi Keuangan', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 40000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 50, OH, @ 800000 )', '1. Paket Meeting Literasi Keuangan ( 50, OH, @ 800000 );', 'Paket meeting literasi keuangan dilaksanakan dalam rangka meningkatkan pemahaman dan kapasitas peserta mengenai pengelolaan keuangan yang baik dan berkelanjutan. Kegiatan ini bertujuan untuk memberikan pengetahuan dan keterampilan kepada peserta terkait perencanaan keuangan, pengelolaan pendapatan dan pengeluaran, pemanfaatan layanan keuangan, serta peningkatan kesadaran akan pentingnya literasi keuangan dalam mendukung kegiatan ekonomi masyarakat. Kegiatan ini dilaksanakan dengan total 50 Orang Hari (OH) yang melibatkan peserta dari unsur pelaksana program, kelompok masyarakat, pendamping lapangan, serta pihak terkait lainnya yang memiliki peran dalam mendukung penguatan kapasitas masyarakat di bidang pengelolaan keuangan. Dalam kegiatan ini peserta akan mendapatkan materi mengenai dasar-dasar literasi keuangan, pengelolaan keuangan rumah tangga, perencanaan usaha, serta pemanfaatan lembaga dan layanan keuangan secara bijak dan bertanggung jawab. Pelaksanaan kegiatan difasilitasi melalui paket meeting yang menyediakan sarana dan prasarana pertemuan yang memadai untuk mendukung proses pembelajaran dan diskusi. Fasilitas yang disediakan meliputi ruang pertemuan yang representatif, peralatan presentasi seperti LCD proyektor, layar, sound system, meja dan kursi rapat atau pelatihan, serta perlengkapan pendukung lainnya yang diperlukan selama kegiatan berlangsung. Selain penyediaan fasilitas ruang pertemuan dan perlengkapan kegiatan, paket meeting juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung, seperti makan dan coffee break sesuai dengan standar pelaksanaan kegiatan rapat atau pelatihan. Hal ini bertujuan untuk menunjang kenyamanan peserta sehingga kegiatan dapat berlangsung secara efektif dan peserta dapat mengikuti seluruh rangkaian materi dengan baik. Melalui kegiatan literasi keuangan ini diharapkan peserta dapat meningkatkan kemampuan dalam mengelola keuangan secara lebih terencana, memahami berbagai pilihan layanan keuangan yang tersedia, serta mampu menerapkan pengetahuan tersebut dalam kegiatan ekonomi sehari-hari. Dengan demikian, kegiatan ini diharapkan dapat mendukung peningkatan kemandirian ekonomi dan kesejahteraan masyarakat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529062);
