INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094001', 66094001, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 22800000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 38, OH, @ 600000 )', '1. Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND ( 38, OH, @ 600000 );', 'Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND merupakan layanan penyelenggaraan rapat yang disediakan oleh pihak hotel atau tempat pertemuan yang memenuhi standar kegiatan resmi. Paket ini diperuntukkan bagi 38 Orang Hari (OH) dengan satuan biaya Rp600.000 per orang per hari, yang mencakup seluruh kebutuhan utama peserta selama kegiatan berlangsung. Paket meeting fullboard meliputi penyediaan ruang pertemuan yang representatif dan nyaman, dengan kapasitas yang memadai untuk menampung seluruh peserta kegiatan. Ruangan dilengkapi dengan fasilitas standar pertemuan, seperti meja dan kursi sesuai tata letak kegiatan (classroom, U-shape, atau theater), LCD proyektor, layar proyektor, sound system, microphone, flipchart, papan tulis, serta akses listrik dan koneksi internet yang mendukung kelancaran pelaksanaan rapat, diskusi, dan presentasi selama kegiatan berlangsung. Selain fasilitas ruang pertemuan, paket fullboard juga mencakup konsumsi bagi peserta selama kegiatan, yang terdiri dari tiga kali makan utama (sarapan, makan siang, dan makan malam) serta dua kali coffee break setiap harinya. Menu konsumsi disediakan oleh pihak penyedia jasa dengan memperhatikan standar kebersihan, kualitas makanan, dan kecukupan gizi bagi peserta kegiatan. Dalam paket ini juga termasuk fasilitas akomodasi atau penginapan bagi peserta, berupa kamar hotel yang layak dan nyaman sesuai standar hotel penyelenggara kegiatan. Fasilitas kamar mencakup tempat tidur, kamar mandi dalam, perlengkapan mandi, pendingin ruangan, serta fasilitas penunjang lainnya yang memungkinkan peserta beristirahat dengan baik selama kegiatan berlangsung. Penyedia paket fullboard juga bertanggung jawab dalam menyediakan layanan pendukung kegiatan, seperti petugas hotel yang membantu pengaturan ruang rapat, kesiapan peralatan, kebersihan ruangan, serta kelancaran distribusi konsumsi kepada peserta. Seluruh layanan tersebut diberikan selama durasi kegiatan berlangsung guna memastikan kegiatan rapat berjalan secara efektif, tertib, dan kondusif. Dengan demikian, paket meeting fullboard ini dirancang untuk memenuhi seluruh kebutuhan dasar penyelenggaraan kegiatan rapat dalam rangka penyiapan exit strategi dan keberlanjutan Program UPLAND, sehingga peserta dapat mengikuti seluruh rangkaian kegiatan secara optimal tanpa terkendala oleh aspek fasilitas maupun konsumsi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529073);
