INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094061', 66094061, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND (2 kali x 30 orang)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 36000000, 'March 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 1, '( 60, OH, @ 600000 )', '1. Pertemuan koordinasi, pembinaan, monitoring, evaluasi dan sinkronisasi UPLAND (2 kali x 30 orang) ( 60, OH, @ 600000 );', 'Kegiatan pertemuan koordinasi, pembinaan, monitoring, evaluasi, dan sinkronisasi UPLAND dilaksanakan sebanyak 2 (dua) kali dengan jumlah peserta masing-masing 30 orang, sehingga total 60 orang hari (OH). Kegiatan ini bertujuan untuk memastikan keselarasan pelaksanaan program, peningkatan kapasitas pelaksana, serta evaluasi capaian dan kendala kegiatan di lapangan. Biaya satuan sebesar Rp600.000 per orang hari mencakup kebutuhan pelaksanaan kegiatan seperti konsumsi rapat, paket meeting (ATK dan materi), serta dukungan operasional lainnya yang diperlukan selama kegiatan berlangsung. Pelaksanaan kegiatan harus terkoordinasi dengan baik, didukung fasilitas yang memadai, serta terdokumentasi sesuai ketentuan administrasi yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529089);
