INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093998', 66093998, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 50, OH, @ 600000 )', '1. Paket meeting fullboard dalam rangka kegiatan UPLAND Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND ( 50, OH, @ 600000 );', 'Paket meeting fullboard dalam rangka kegiatan Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND disediakan untuk mendukung kelancaran pelaksanaan kegiatan rapat/koordinasi yang melibatkan peserta sebanyak 50 Orang Hari (OH) dengan standar biaya Rp600.000 per orang per hari. Paket ini mencakup fasilitas ruang pertemuan, konsumsi, serta sarana pendukung kegiatan selama satu hari penuh. Ruang pertemuan yang disediakan merupakan ruang yang representatif, nyaman, berpendingin udara (AC), serta mampu menampung seluruh peserta dengan tata letak sesuai kebutuhan kegiatan (classroom, U-shape, atau theatre). Ruangan dilengkapi dengan fasilitas pendukung seperti LCD proyektor, layar proyeksi, sound system standar, microphone (wired/wireless), flipchart/whiteboard beserta alat tulisnya, serta akses listrik yang memadai untuk mendukung presentasi dan diskusi. Selain itu, tersedia meja registrasi dan area penunjang kegiatan yang mendukung kelancaran pelaksanaan rapat. Dalam paket fullboard ini juga termasuk konsumsi peserta selama kegiatan, yang terdiri dari 1 (satu) kali makan siang, 2 (dua) kali coffee break (pagi dan sore) yang masing-masing dilengkapi dengan makanan ringan/snack dan minuman (kopi/teh), serta 1 (satu) kali makan malam. Penyedia jasa memastikan kualitas makanan yang higienis, cukup, dan sesuai standar pelayanan pertemuan. Selain fasilitas ruang dan konsumsi, paket juga mencakup penggunaan perlengkapan rapat dasar seperti air mineral untuk peserta, notepad, dan alat tulis, serta layanan teknis dari pihak penyedia tempat untuk membantu pengoperasian peralatan selama kegiatan berlangsung. Dengan demikian, paket meeting fullboard sebesar Rp600.000 per orang per hari untuk 50 OH ini dirancang untuk memberikan layanan pertemuan yang lengkap dan memadai guna mendukung efektivitas pelaksanaan kegiatan Penyiapan Exit Strategi dan Keberlanjutan Program UPLAND, sehingga proses diskusi, koordinasi, dan perumusan strategi dapat berjalan dengan baik, tertib, dan produktif', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529170);
