INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093528', 66093528, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN LAPORAN ANALISIS TATA KELOLA DAN MANAJEMEN INTERNAL KOORDINASI STRATEGIS PROGRAM MAKAN BERGIZI GRATIS (MBG) TAHUN 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82200000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'a. Mengkoordinasikan proses tata kelola dan manajemen keuangan kerja sama Kementerian PPN/Bappenas-BGN sesuai kaidah tata kelola pemerintah dan akuntabilitas b. Mendukung pelaksanaan koordinasi tata kelola administrasi, keuangan, substansi dan pengadaan barang dan jasa bersama dengan PPK dan PPBJ; c. Memfasilitasi dukungan tata kelola dan manajemen keuangan, serta pelaporan substansi kegiatan d. Melakukan pengawalan penggunaan anggaran dan koordinasi penggunaan anggaran dengan inspektorat, BPKP, dan kementerian/lembaga terkait lainnya. e. Menyusun laporan tata kelola dan manajemen keuangan dalam pelaksanaan kegiatan dari berbagai sumber-sumber pendanaan. f. Membantu perencanaan dan penganggaran dalam menyusun anggaran tahunan dan memproyeksikan kebutuhan anggaran untuk operasional sekretariat dan unit kerja. g. Membantu pengelolaan dana dalam mengatur komposisi anggaran dalam setiap unit kerja, arus kas (cash flow), dan memastikan penganggaran tersedia dalam pelaksanaan kegiatan.', 'a. Mengkoordinasikan proses tata kelola dan manajemen keuangan kerja sama Kementerian PPN/Bappenas-BGN sesuai kaidah tata kelola pemerintah dan akuntabilitas b. Mendukung pelaksanaan koordinasi tata kelola administrasi, keuangan, substansi dan pengadaan barang dan jasa bersama dengan PPK dan PPBJ; c. Memfasilitasi dukungan tata kelola dan manajemen keuangan, serta pelaporan substansi kegiatan d. Melakukan pengawalan penggunaan anggaran dan koordinasi penggunaan anggaran dengan inspektorat, BPKP, dan kementerian/lembaga terkait lainnya. e. Menyusun laporan tata kelola dan manajemen keuangan dalam pelaksanaan kegiatan dari berbagai sumber-sumber pendanaan. f. Membantu perencanaan dan penganggaran dalam menyusun anggaran tahunan dan memproyeksikan kebutuhan anggaran untuk operasional sekretariat dan unit kerja. g. Membantu pengelolaan dana dalam mengatur komposisi anggaran dalam setiap unit kerja, arus kas (cash flow), dan memastikan penganggaran tersedia dalam pelaksanaan kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529261);
