INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66055108', 66055108, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Pemeliharaan Kamera Video dan Lensa', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 90000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 Unit', 'Layanan perawatan berkala dan penanganan gangguan (corrective maintenance) terhadap seluruh unit kamera video dan lensa milik/yang digunakan Biro Humas Kemnaker untuk mendukung kegiatan peliputan, dokumentasi, dan produksi konten, meliputi inspeksi kondisi fisik dan fungsi, pembersihan menyeluruh (body, mount, sensor/optik sesuai prosedur aman), pengecekan dan penyetelan dasar (fokus, zoom, aperture/iris, stabilizer, tombol/port, hot shoe, viewfinder/monitor), uji performa perekaman (audio-video), pembaruan firmware bila diperlukan, perbaikan kerusakan ringan–sedang sesuai hasil diagnosis, penggantian suku cadang/consumables yang aus (jika dibutuhkan), serta penyusunan laporan hasil servis berikut rekomendasi tindak lanjut sampai diterbitkannya berita acara layanan/serah terima hasil pekerjaan.', 'Penyedia wajib memiliki kompetensi teknis servis kamera dan lensa (teknisi berpengalaman) serta mampu menangani berbagai merek/tipe, menggunakan metode kerja yang aman untuk optik/sensor (anti-statis, tools khusus, cairan pembersih sesuai standar), melakukan pemeriksaan fungsional minimal meliputi: kualitas gambar (ketajaman, fokus, stabilitas, noise), fungsi lensa (zoom ring/focus ring/aperture, AF/MF, stabilizer), konektivitas dan port (HDMI/SDI/USB/mic-in/line), media rekam (slot/memory card), baterai/charger, serta memastikan unit lulus uji coba perekaman dengan hasil rekaman contoh sebelum dikembalikan; penggantian suku cadang harus kompatibel dan diutamakan original/berkualitas setara, setiap tindakan servis terdokumentasi (checklist sebelum-sesudah, temuan kerusakan, tindakan perbaikan, parts yang diganti), disertai garansi layanan untuk pekerjaan/pergantian yang dilakukan, dan memenuhi SLA waktu penanganan (respon/diagnosis/perbaikan) sesuai yang ditetapkan dalam kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529399);
