INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093955', 66093955, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsultan Individu Bidang Alsin pasca panen', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 200000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 10, OB, @ 20000000 )', '1. Konsultan Individu Bidang Alsin pasca panen ( 10, OB, @ 20000000 );', 'Pengadaan Konsultan Individu Bidang Alat dan Mesin (Alsin) Pasca Panen dilaksanakan selama 10 (sepuluh) orang bulan (OB) dengan besaran honorarium Rp20.000.000 per orang bulan. Konsultan bertugas memberikan dukungan teknis dalam perencanaan, pendampingan, pengawasan, serta evaluasi kegiatan terkait pengelolaan dan optimalisasi alsin pasca panen dalam lingkup program. Ruang lingkup pekerjaan meliputi analisis kebutuhan alsin pasca panen, penyusunan rekomendasi teknis, pendampingan implementasi di lapangan, koordinasi dengan pemangku kepentingan terkait, serta penyusunan laporan berkala dan laporan akhir. Konsultan juga bertanggung jawab memastikan pemanfaatan alsin berjalan efektif, efisien, dan sesuai dengan pedoman teknis yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529425);
