INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094019', 66094019, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsumsi Rapat', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 56250000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 750, OK, @ 75000 )', '1. Konsumsi Rapat ( 750, OK, @ 75000 );', 'Konsumsi rapat merupakan penyediaan makanan dan minuman yang diperuntukkan bagi peserta rapat dalam rangka mendukung kelancaran pelaksanaan kegiatan pertemuan, koordinasi, pembahasan teknis, serta evaluasi kegiatan program. Kegiatan ini dialokasikan sebanyak 750 Orang Konsumsi (OK) dengan satuan biaya sebesar Rp75.000 per orang. Penyediaan konsumsi rapat bertujuan untuk menunjang berbagai kegiatan pertemuan yang melibatkan tim pelaksana, pemangku kepentingan, maupun pihak terkait lainnya dalam rangka pelaksanaan kegiatan program. Konsumsi yang disediakan umumnya berupa makanan ringan/snack dan minuman, atau dapat juga berupa makanan kotak (box meal) sesuai dengan kebutuhan dan waktu pelaksanaan rapat. Konsumsi rapat disediakan dengan memperhatikan standar kebersihan, kualitas makanan, serta kelayakan konsumsi, sehingga peserta rapat dapat mengikuti kegiatan dengan nyaman dan tetap fokus pada proses diskusi maupun pengambilan keputusan. Penyediaan konsumsi dilakukan sesuai dengan jumlah peserta yang hadir dalam setiap kegiatan rapat. Dengan adanya dukungan konsumsi rapat ini, diharapkan pelaksanaan kegiatan rapat, koordinasi, serta pembahasan teknis dapat berjalan secara lebih efektif, tertib, dan kondusif, sehingga mendukung kelancaran pelaksanaan program serta tercapainya tujuan kegiatan yang telah direncanakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529483);
