INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094025', 66094025, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Fullboard dalam rangka Monitoring dan Evaluasi', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 50, OH, @ 600000 )', '1. Paket Meeting Fullboard dalam rangka Monitoring dan Evaluasi ( 50, OH, @ 600000 );', 'Paket meeting fullboard dalam rangka kegiatan Monitoring dan Evaluasi merupakan layanan penyelenggaraan pertemuan yang disediakan oleh hotel atau tempat pertemuan yang memiliki fasilitas memadai untuk mendukung pelaksanaan kegiatan secara efektif dan kondusif. Kegiatan ini dialokasikan sebanyak 50 Orang Hari (OH) dengan satuan biaya sebesar Rp600.000 per orang per hari. Paket meeting fullboard mencakup penyediaan ruang pertemuan yang representatif dan nyaman dengan kapasitas yang memadai sesuai jumlah peserta. Ruang pertemuan dilengkapi dengan berbagai fasilitas pendukung kegiatan rapat seperti meja dan kursi sesuai tata letak pertemuan (classroom, U-shape, atau theater), LCD proyektor, layar proyektor, sound system, microphone, papan tulis atau flipchart, serta akses listrik dan jaringan internet guna menunjang kegiatan presentasi, diskusi, dan penyampaian laporan selama kegiatan berlangsung. Selain penyediaan ruang pertemuan, paket fullboard juga mencakup konsumsi bagi peserta selama kegiatan berlangsung, yang terdiri dari tiga kali makan utama (sarapan, makan siang, dan makan malam) serta dua kali coffee break setiap hari kegiatan. Konsumsi disediakan oleh penyedia jasa dengan memperhatikan standar kebersihan, kualitas makanan, serta kecukupan gizi bagi seluruh peserta kegiatan. Paket ini juga mencakup fasilitas akomodasi atau penginapan bagi peserta, berupa kamar hotel yang layak dan nyaman sesuai standar tempat kegiatan. Fasilitas kamar biasanya meliputi tempat tidur, kamar mandi dalam, perlengkapan mandi, pendingin ruangan, serta fasilitas penunjang lainnya yang mendukung kenyamanan peserta selama kegiatan berlangsung. Selain itu, penyedia jasa juga memberikan dukungan layanan teknis dan operasional, seperti penataan ruang rapat, kesiapan peralatan presentasi, kebersihan ruangan, serta pelayanan konsumsi bagi peserta kegiatan. Layanan ini diberikan untuk memastikan bahwa seluruh rangkaian kegiatan monitoring dan evaluasi dapat berjalan dengan lancar dan sesuai dengan agenda yang telah direncanakan. Dengan tersedianya paket meeting fullboard ini, diharapkan kegiatan monitoring dan evaluasi pelaksanaan program dapat terlaksana secara optimal, sehingga menghasilkan pembahasan yang komprehensif mengenai capaian kegiatan, identifikasi permasalahan, serta penyusunan rekomendasi perbaikan guna meningkatkan kualitas pelaksanaan program di masa yang akan datang.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529489);
