INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094003', 66094003, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting Fullboard dalam rangka Monitoring dan Evaluasi', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 50, OH, @ 600000 )', '1. Paket Meeting Fullboard dalam rangka Monitoring dan Evaluasi ( 50, OH, @ 600000 );', 'Pengadaan paket meeting fullboard dalam rangka kegiatan monitoring dan evaluasi dilaksanakan sebanyak 50 (lima puluh) orang hari (OH) dengan satuan biaya sebesar Rp600.000 per orang hari. Kegiatan ini bertujuan untuk memfasilitasi pelaksanaan rapat monitoring dan evaluasi program agar berjalan efektif, terkoordinasi, serta menghasilkan rekomendasi perbaikan pelaksanaan kegiatan. Paket fullboard meliputi penyediaan ruang rapat yang representatif, akomodasi/penginapan peserta, konsumsi berupa 3 (tiga) kali makan utama dan 2 (dua) kali coffee break per hari, serta fasilitas pendukung seperti LCD proyektor, layar, sound system, meja dan kursi rapat, alat tulis kantor, dan air mineral. Penyedia wajib memastikan kualitas layanan, kebersihan dan kenyamanan tempat, kelengkapan fasilitas rapat, serta ketepatan waktu penyajian konsumsi selama kegiatan berlangsung. Seluruh pelaksanaan kegiatan harus didukung dengan dokumentasi serta bukti transaksi yang sah sesuai ketentuan administrasi yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529503);
