INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093997', 66093997, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Project Management Specialist', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 240000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 20, OB, @ 12000000 )', '1. Project Management Specialist ( 20, OB, @ 12000000 );', 'Project Management Specialist merupakan tenaga ahli yang bertugas mendukung pelaksanaan dan pengelolaan kegiatan proyek agar berjalan secara efektif, efisien, serta sesuai dengan rencana kerja dan target yang telah ditetapkan. Tenaga ahli ini berperan dalam membantu manajemen proyek dalam proses perencanaan, pelaksanaan, koordinasi, monitoring, dan evaluasi kegiatan proyek. Dalam pelaksanaan tugasnya, Project Management Specialist bertanggung jawab untuk memberikan dukungan teknis dalam penyusunan rencana kerja kegiatan proyek, melakukan koordinasi dengan tim pelaksana kegiatan, konsultan, serta pihak terkait lainnya guna memastikan kegiatan berjalan sesuai jadwal dan ketentuan yang berlaku. Selain itu, tenaga ahli ini juga melakukan pemantauan terhadap pelaksanaan kegiatan proyek, mengidentifikasi potensi kendala yang dapat mempengaruhi pencapaian target program, serta memberikan rekomendasi solusi kepada manajemen proyek. Project Management Specialist juga berperan dalam mendukung pelaksanaan kegiatan monitoring dan evaluasi, termasuk pengumpulan data dan informasi yang diperlukan untuk menilai capaian kegiatan proyek. Hasil pemantauan tersebut kemudian digunakan sebagai bahan dalam penyusunan laporan pelaksanaan kegiatan proyek secara berkala serta sebagai dasar dalam pengambilan keputusan manajerial. Selain itu, tenaga ahli ini turut membantu dalam pendokumentasian kegiatan proyek dan penyusunan berbagai laporan yang diperlukan oleh manajemen proyek maupun pemangku kepentingan terkait. Dengan adanya dukungan dari Project Management Specialist, diharapkan pelaksanaan kegiatan proyek dapat berjalan lebih terarah, terkoordinasi dengan baik, serta mampu mencapai sasaran program secara optimal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529629);
