INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093114', 66093114, 'analyze_legacy', 'Kab. Tangerang', 'kabkota', 'Kecamatan Mauk', 'Belanja Modal Peralatan Studio Video dan Film', 'Barang', 'E-Purchasing', 'Banten, Tangerang (Kab.)', 57755000, 'July 2026', 'APBD', 1, 1, '2 Paket', '[ # ] PENYEDIAAN PERALATAN DAN PERLENGKAPAN KANTOR [ - ] Drone Drone Premium Spesifikasi: Kamera CMOS 4/3 100 MP, video hingga 6K/60fps, gimbal rotasi 360° 1 Unit Buah [ - ] Kamera Digital Kamera Digital Spesifikasi: Standar 1 Unit Unit', '[ # ] PENYEDIAAN PERALATAN DAN PERLENGKAPAN KANTOR [ - ] Drone Drone Premium Spesifikasi: Kamera CMOS 4/3 100 MP, video hingga 6K/60fps, gimbal rotasi 360° 1 Unit Buah [ - ] Kamera Digital Kamera Digital Spesifikasi: Standar 1 Unit Unit', 30000000, 'high', 'Pengadaan drone premium berspesifikasi sangat tinggi untuk unit kecamatan berindikasi tidak proporsional dengan kebutuhan operasional kantor pemerintahan umum. Spesifikasi seperti kamera 4/3 100 MP dan video 6K/60fps cenderung melampaui kebutuhan dokumentasi standar, sehingga layak dicermati sebagai potensi belanja berlebihan.', NULL, NULL, 3, 1, 1, 1, 1, 2529698);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094121', 66094121, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket meeting dalam rangka Rapat, Workshop, FGD Exit Strategi Keg Upland', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 320000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 400, OH, @ 800000 )', '1. Paket meeting dalam rangka Rapat, Workshop, FGD Exit Strategi Keg Upland ( 400, OH, @ 800000 );', 'Paket meeting dalam rangka rapat, workshop, dan Focus Group Discussion (FGD) exit strategi kegiatan UPLAND dilaksanakan sebagai bagian dari proses perencanaan keberlanjutan program setelah masa implementasi kegiatan berakhir. Kegiatan ini bertujuan untuk merumuskan strategi keluar (exit strategy) yang terencana dan berkelanjutan sehingga hasil-hasil program yang telah dicapai dapat tetap memberikan manfaat bagi masyarakat serta dapat dilanjutkan oleh para pemangku kepentingan terkait. Kegiatan ini dilaksanakan dengan total 400 Orang Hari (OH) yang melibatkan berbagai pihak terkait, antara lain pengelola program, perwakilan pemerintah daerah, penyuluh pertanian, fasilitator lapangan, kelompok tani, serta pemangku kepentingan lainnya yang memiliki peran dalam pelaksanaan dan keberlanjutan program UPLAND. Melalui kegiatan rapat, workshop, dan FGD ini, para peserta akan melakukan pembahasan secara komprehensif mengenai capaian program, pembelajaran yang diperoleh selama pelaksanaan kegiatan, serta berbagai faktor yang dapat mendukung keberlanjutan program di masa mendatang. Dalam kegiatan ini juga akan dilakukan identifikasi terhadap potensi kelembagaan, sumber daya, serta dukungan kebijakan yang dapat dimanfaatkan untuk melanjutkan kegiatan yang telah berjalan. Selain itu, peserta juga akan menyusun rekomendasi serta rencana tindak lanjut yang dapat menjadi dasar dalam pelaksanaan strategi keberlanjutan program di tingkat daerah maupun masyarakat. Pelaksanaan kegiatan difasilitasi melalui paket meeting yang menyediakan sarana dan prasarana pertemuan yang memadai. Fasilitas yang disediakan meliputi ruang pertemuan yang representatif, peralatan presentasi seperti LCD proyektor, layar, sound system, meja dan kursi pertemuan, serta perlengkapan penunjang lainnya yang diperlukan selama kegiatan berlangsung. Selain penyediaan fasilitas ruang pertemuan dan perlengkapan kegiatan, paket meeting juga mencakup penyediaan konsumsi bagi peserta selama kegiatan berlangsung, seperti makan dan coffee break sesuai dengan standar pelaksanaan kegiatan rapat atau pertemuan. Penyediaan fasilitas tersebut bertujuan untuk menunjang kenyamanan peserta sehingga proses diskusi, pertukaran informasi, serta perumusan strategi dapat berjalan secara efektif. Melalui kegiatan ini diharapkan dapat dihasilkan rumusan exit strategi kegiatan UPLAND yang komprehensif, realistis, dan dapat diimplementasikan secara berkelanjutan oleh para pemangku kepentingan. Dengan demikian, manfaat program yang telah dilaksanakan dapat terus dirasakan oleh masyarakat serta mendukung pengembangan sektor pertanian dan pemberdayaan masyarakat secara berkelanjutan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529699);
