INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094016', 66094016, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket meeting dalam rangka Rapat, Workshop, FGD', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 360000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 400, OH, @ 900000 )', '1. Paket meeting dalam rangka Rapat, Workshop, FGD ( 400, OH, @ 900000 );', 'Paket Meeting dalam rangka Rapat, Workshop, dan Focus Group Discussion (FGD) merupakan penyediaan layanan pertemuan untuk mendukung pelaksanaan kegiatan koordinasi, pembahasan teknis, serta penggalian informasi dan masukan dari para pemangku kepentingan dalam rangka mendukung pelaksanaan kegiatan program. Paket ini disediakan untuk memastikan kegiatan rapat, workshop, dan FGD dapat berlangsung secara efektif, tertib, dan produktif. Paket meeting ini mencakup penyediaan ruang pertemuan yang layak dan representatif sesuai dengan kapasitas peserta kegiatan, serta dilengkapi dengan fasilitas pendukung seperti meja, kursi, pendingin ruangan, LCD projector, layar presentasi, sound system, microphone, dan fasilitas lainnya yang diperlukan untuk menunjang kelancaran jalannya kegiatan. Selain itu, paket meeting juga mencakup penyediaan konsumsi bagi peserta kegiatan selama pelaksanaan rapat, workshop, maupun FGD, seperti makan siang dan coffee break sesuai dengan standar layanan kegiatan pertemuan. Penyedia layanan juga diharapkan memberikan dukungan teknis selama kegiatan berlangsung guna memastikan kegiatan dapat berjalan dengan lancar tanpa kendala teknis. Kegiatan rapat, workshop, dan FGD ini bertujuan untuk memfasilitasi koordinasi, diskusi, serta pertukaran informasi dan gagasan antar peserta guna menghasilkan rekomendasi, rumusan kebijakan, atau rencana tindak lanjut yang mendukung pencapaian tujuan program. Dengan tersedianya paket meeting ini, diharapkan pelaksanaan kegiatan rapat, workshop, dan FGD dapat berlangsung secara kondusif, efektif, dan menghasilkan output yang bermanfaat bagi pelaksanaan kegiatan program.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529719);
