INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66094919', 66094919, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Paket Meeting (35 Orang x 3 hari)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 70420000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1. Paket Meeting (35 Orang x 3 hari) ( 70, OP, @ 1006000 );', '1. Paket Meeting (35 Orang x 3 hari) ( 70, OP, @ 1006000 );', 'Kegiatan Paket Meeting Full Board dilaksanakan dalam rangka rapat koordinasi pelaksanaan kegiatan penyusunan dokumen pengembangan irigasi tersier. Kegiatan ini bertujuan untuk menyamakan persepsi, membahas substansi teknis, melakukan pendalaman data, serta merumuskan langkah tindak lanjut dalam proses penyusunan dokumen agar sesuai dengan ketentuan perencanaan dan kebutuhan lapangan. Meeting dilaksanakan selama 3 (tiga) hari dengan melibatkan 35 (tiga puluh lima) orang peserta yang terdiri dari unsur teknis pusat dan/atau daerah, tim perencana, penyusun dokumen, serta pihak terkait lainnya. Pelaksanaan secara full board dimaksudkan agar pembahasan dapat dilakukan secara intensif, terintegrasi, dan menghasilkan kesepakatan yang komprehensif dalam satu rangkaian kegiatan. Paket meeting full board mencakup penyediaan ruang pertemuan yang representatif, akomodasi penginapan peserta, konsumsi lengkap (makan pagi, siang, malam, dan coffee break), serta perlengkapan rapat seperti ATK dan bahan tayang sesuai standar biaya yang berlaku. Seluruh fasilitas disediakan untuk mendukung kelancaran, kenyamanan, dan efektivitas proses koordinasi dan pembahasan teknis. Output yang diharapkan dari kegiatan ini adalah tersusunnya draft atau penyempurnaan dokumen pengembangan irigasi tersier yang telah dibahas dan disepakati bersama, lengkap dengan berita acara dan rencana tindak lanjut', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529733);
