INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093904', 66093904, 'analyze_legacy', 'Kementerian Hak Asasi Manusia', 'central', 'SEKRETARIAT JENDERAL KEMENTERIAN HAM', 'Pengadaan Jasa Pelaksanaan Kegiatan Konsinyering Rencana Aksi (Action Plan) Tindak Lanjut Kementerian HAM atas Laporan Hasil Pemeriksaan BPK', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 200000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Melaksanana kegiatan konsinyering rencana aksi tindak lanjut kementerian HAM atas laporan hasil pemeriksaan BPK', '- Melaksanakan pekerjaan sesuai kebutuhan pengguna jasa. Menyediakan tenaga kerja yang kompeten dan memenuhi kualifikasi. Menyediakan peralatan kerja pendukung (apabila dipersyaratkan). Melaksanakan pekerjaan sesuai jadwal dan standar mutu. Menyampaikan laporan pelaksanaan pekerjaan secara berkala.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529740);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66054918', 66054918, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Biaya Pemeliharaan dan Operasional Kendaraan Roda 2', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 31248000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '7 Unit', 'Kegiatan penyediaan layanan dan kebutuhan untuk menjaga kendaraan roda dua milik/yang digunakan satuan kerja tetap laik jalan, aman, dan siap mendukung kegiatan operasional kedinasan, melalui pemeliharaan rutin dan berkala (pemeriksaan umum, servis ringan/berat, penyetelan), perbaikan atas kerusakan, serta pengadaan/penggantian bahan habis pakai dan komponen sesuai kebutuhan nyata selama periode pelaksanaan (misalnya pelumas, kampas rem, ban, aki, busi, rantai–sprocket, lampu, dan komponen sejenis), termasuk kebutuhan operasional yang melekat pada penggunaan kendaraan sesuai ketentuan yang berlaku; penyusunan kebutuhan dan kewajaran biaya mengacu pada Standar Biaya Masukan TA 2026.', 'Ruang lingkup pekerjaan meliputi (i) jasa pemeliharaan/perbaikan kendaraan roda dua oleh penyedia/bengkel yang berizin dan memiliki mekanik kompeten, (ii) penggunaan suku cadang dan material baru yang sesuai/kompatibel dengan spesifikasi teknis kendaraan (setara standar pabrikan) serta pelumas dengan mutu sesuai rekomendasi pabrikan, (iii) standar pelaksanaan pekerjaan mengikuti prosedur pemeliharaan yang dapat dipertanggungjawabkan (diagnosa, tindakan perbaikan, uji fungsi akhir), (iv) setiap transaksi wajib disertai bukti sah (invoice/kuitansi/nota, rincian item, dan laporan singkat pekerjaan) untuk mendukung verifikasi tagihan, serta (v) hasil akhir memastikan kendaraan berfungsi normal, aman dikendarai, dan siap operasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529741);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66056620', 66056620, 'analyze_legacy', 'Provinsi Nusa Tenggara Barat', 'provinsi', 'Dinas Kesehatan', 'Belanja Alat/Bahan untuk Kegiatan Kantor- Bahan Cetak, Cetak Humas, Cetak Lembar Disposisi,  Cetak Map Kop, Penggandaan, Penjilidan', 'Barang', 'Pengadaan Langsung', 'Nusa Tenggara Barat, Mataram (Kota)', 20000000, 'January 2026', 'APBD', 1, 1, '1 Tahun', 'Bahan Cetak; Bahan Cetak; Bahan Cetak; Bahan Cetak; Bahan Cetak;', 'Cetak buku lembar disposisi 15 X 21 cm isi 100 lbr; Spanduk/Baliho dan sejenisnya (bahan Vinyl); Fotocopy bahan HVS 70 gr pulau lombok 1 muka; Cetak Cover dan Jilid Bahan Kertas Gelori/ kingstrik; Map Kop OPD/ UPT;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529742);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093971', 66093971, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Konsultan Individu Bidang Lingkungan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 200000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 10, OB, @ 20000000 )', '1. Konsultan Individu Bidang Lingkungan ( 10, OB, @ 20000000 );', 'Pengadaan Konsultan Individu Bidang Lingkungan dilaksanakan selama 10 (sepuluh) orang bulan (OB) dengan besaran honorarium Rp20.000.000 per orang bulan. Konsultan bertugas memberikan dukungan teknis dalam memastikan aspek perlindungan dan pengelolaan lingkungan terintegrasi dalam perencanaan dan pelaksanaan kegiatan program. Ruang lingkup pekerjaan meliputi identifikasi dan analisis dampak lingkungan, penyusunan dokumen dan rekomendasi pengelolaan serta pemantauan lingkungan, pendampingan penerapan praktik ramah lingkungan di lapangan, serta koordinasi dengan pemangku kepentingan terkait. Konsultan juga bertanggung jawab melakukan monitoring dan evaluasi kepatuhan terhadap ketentuan lingkungan serta menyusun laporan berkala dan laporan akhir. Pelaksanaan tugas harus menghasilkan rekomendasi yang aplikatif, berbasis data, serta sesuai dengan peraturan dan pedoman teknis lingkungan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2529743);
